-- ════════════════ 019_gwei_currency.sql ════════════════
-- 019: Gwei, the game's own fictional currency (never on-chain). Earned by validators, quests, mobs;
-- spent on repairs, upgrades, and cosmetics. A server-only counter on the player row, like rewards_at.
-- Requires 001_schema.sql. Replayable without error.

alter table public.players add column if not exists gwei bigint not null default 0;

create or replace function public._gwei_balance(me uuid, w text) returns bigint
language sql stable security definer set search_path = public as $$
  select coalesce((select gwei from players where user_id = me and world = w), 0)
$$;

-- Adds (or removes, if d < 0) Gwei from the player's balance; never goes negative. Callers that spend
-- Gwei check _gwei_balance first (same convention as _give/_count for inventory items).
create or replace function public._gwei(me uuid, w text, d bigint) returns bigint
language plpgsql security definer set search_path = public as $$
declare v bigint;
begin
  update players set gwei = gwei + d where user_id = me and world = w returning gwei into v;
  if v is null or v < 0 then raise exception 'not enough gwei'; end if;
  return v;
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 020_validators.sql ════════════════
-- 020: validators become real rows (position, state, rarity, level, production), not just a block id
-- counted on the fly. A validator is dormant until reanimated (relit from a ruin, or crafted and placed);
-- its seal (item 203, already non-transferable) now points at the row instead of carrying raw onchain
-- coordinates.
-- Requires 001_schema.sql, 002_security.sql, 012_relight_column.sql. Replayable without error.

create table if not exists public.validators (
  id               bigserial   primary key,
  world            text        not null,
  x                integer     not null,
  y                integer     not null,
  z                integer     not null,
  owner            uuid        references auth.users (id) on delete cascade,
  owner_name       text,
  state            text        not null default 'dormant' check (state in ('dormant', 'active', 'damaged', 'corrupted')),
  rarity           text        not null default 'common' check (rarity in ('common', 'rare', 'epic', 'legendary')),
  level            smallint    not null default 1,
  specialty        text        check (specialty in ('production', 'defense', 'exploration', 'craft')),
  gwei_per_cycle   integer     not null default 0,
  maintenance_cost integer     not null default 0,
  missed_cycles    integer     not null default 0,
  last_cycle_at    timestamptz,
  last_attested_at timestamptz,
  reanimated_at    timestamptz,
  created_at       timestamptz not null default now(),
  unique (world, x, y, z)
);
create index if not exists validators_owner on public.validators (world, owner) where owner is not null;
create index if not exists validators_state on public.validators (world, state);
alter table public.validators enable row level security;
drop policy if exists "read validators" on public.validators;
create policy "read validators" on public.validators for select using (true);

-- The seal now points at its validator row; vx/vy/vz (chain-era) are dropped later in 023_remove_onchain.sql
-- once nothing writes them anymore.
alter table public.uniques add column if not exists validator_id bigint references public.validators (id);
create unique index if not exists uniques_one_seal_per_validator on public.uniques (world, validator_id)
  where item = 203 and validator_id is not null;

-- Rarity at reanimation: common 60%, rare 25%, epic 12%, legendary 3%.
create or replace function public._pick_rarity() returns text
language sql volatile as $$
  select case when r < 0.60 then 'common' when r < 0.85 then 'rare' when r < 0.97 then 'epic' else 'legendary' end
  from (select random() as r) s
$$;

-- Gross production and upkeep per cycle (one cycle = 5 minutes, see _tick_validator), by rarity and level
-- (+15% per level above 1, level 10 at most). Net gain per maintained cycle is gwei_per_cycle - maintenance_cost.
create or replace function public._validator_stats(rarity text, level int) returns jsonb
language sql immutable as $$
  select jsonb_build_object(
    'gwei_per_cycle', floor((case rarity when 'common' then 12 when 'rare' then 25 when 'epic' then 50 else 100 end)
      * (1 + 0.15 * (level - 1)))::int,
    'maintenance_cost', floor((case rarity when 'common' then 2 when 'rare' then 5 when 'epic' then 10 else 20 end)
      * (1 + 0.15 * (level - 1)))::int
  )
$$;

-- Relight a dark validator: same preconditions as before (012/014), now also reanimates a validators row
-- (random rarity) and points the minted seal at it instead of recording raw vx/vy/vz.
create or replace function public._core_relight(w text, px int, py int, pz int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); pl players; inv jsonb := '{}'; s int; ch jsonb := '[]'; u jsonb; star jsonb; solid boolean;
        relit_n int; shard boolean := false; rarity text; stats jsonb; vid bigint;
begin
  pl := _player(me, w);
  if _cell(w, px, py, pz) <> 73 then return _no('not a dark validator', jsonb_build_object('cell', _cell(w, px, py, pz))); end if;
  for i in 0..2 loop
    solid := coalesce((select rb.solid from rule_blocks rb where rb.id = _cell_soft(w, px + 2, py + i, pz + 2)), false);
    if not solid then return _no('rebuild the fourth column first'); end if;
  end loop;
  if _count(me, w, 105) < 1 then return _no('needs a validator heart'); end if;
  inv := _give(me, w, 105, -1, inv);
  update players set serial = serial + 1 where user_id = me and world = w returning serial into s;
  ch := ch || _set(w, px, py, pz, 74, me, pl.name, s);
  rarity := _pick_rarity();
  stats := _validator_stats(rarity, 1);
  insert into validators (world, x, y, z, owner, owner_name, state, rarity, level, gwei_per_cycle, maintenance_cost, reanimated_at, last_cycle_at)
    values (w, px, py, pz, me, pl.name, 'active', rarity, 1, (stats ->> 'gwei_per_cycle')::int, (stats ->> 'maintenance_cost')::int, now(), now())
    on conflict (world, x, y, z) do update set owner = excluded.owner, owner_name = excluded.owner_name, state = 'active',
      rarity = excluded.rarity, level = 1, gwei_per_cycle = excluded.gwei_per_cycle, maintenance_cost = excluded.maintenance_cost,
      missed_cycles = 0, reanimated_at = now(), last_cycle_at = now()
    returning id into vid;
  u := _mint(me, w, 203, px || ', ' || py || ', ' || pz);
  update uniques set validator_id = vid where user_id = me and world = w and serial = (u ->> 'serial')::int;
  select count(*) into relit_n from blocks where world = w and id = 74;
  if relit_n = any (array[3, 10, 25, 50, 100]) then
    star := _mint(me, w, 204, 'crossed the ' || relit_n || '-relit threshold');
  end if;
  if relit_n >= 100 and random() < 0.15 then
    inv := _give(me, w, 110, 1, inv);
    shard := true;
  end if;
  return jsonb_build_object('ok', true, 'changes', ch, 'inv', inv, 'unique', u, 'star', star, 'shard', shard, 'serial', s, 'validator', vid);
end $$;

-- Place: same body as 010_bed.sql's _core_place (door and bed double-placement), except a freshly
-- placed/crafted validator block (13) also reanimates a validators row (always common rarity: crafting
-- it is a shortcut, not a discovery).
create or replace function public._core_place(w text, px int, py int, pz int, it int, bid int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); pl players; cur int; cr rule_blocks; rb rule_blocks; below int; up int; ch jsonb := '[]'; inv jsonb := '{}'; s int;
  odx int; odz int; ocur int; ocr rule_blocks; stats jsonb;
begin
  pl := _player(me, w);
  if py < 1 or py >= 64 or abs(px) >= 100000 or abs(pz) >= 100000 then return _no('out of the world'); end if;
  if not exists (select 1 from rule_place where item = it and block = bid) then return _no('item not placeable'); end if;
  if _count(me, w, it) < 1 then return _no('empty inventory', jsonb_build_object('inv', jsonb_build_object(it::text, 0))); end if;
  if not _can_build(me, w, px, pz) then return _no('protected'); end if;
  cur := _cell(w, px, py, pz); select * into cr from rule_blocks where id = cur;
  if cur <> 0 and cr.kind not in ('water', 'cross') then return _no('space occupied', jsonb_build_object('cell', cur)); end if;
  select * into rb from rule_blocks where id = bid;
  below := _cell(w, px, py - 1, pz);
  if rb.kind = 'cross' and below not in (1, 2) then return _no('needs support'); end if;
  if rb.kind in ('plate', 'cable', 'lever') and not coalesce((select solid from rule_blocks where id = below), false) then return _no('needs support'); end if;
  if rb.kind = 'door' then
    if py + 1 >= 64 then return _no('out of the world'); end if;
    up := _cell(w, px, py + 1, pz);
    if up <> 0 and (select kind from rule_blocks where id = up) not in ('water', 'cross') then return _no('space occupied'); end if;
  elsif rb.kind like 'bed%f' then
    odx := case rb.kind when 'bed0f' then 0 when 'bed1f' then -1 when 'bed2f' then 0 when 'bed3f' then 1 end;
    odz := case rb.kind when 'bed0f' then -1 when 'bed1f' then 0 when 'bed2f' then 1 when 'bed3f' then 0 end;
    ocur := _cell(w, px + odx, py, pz + odz); select * into ocr from rule_blocks where id = ocur;
    if ocur <> 0 and ocr.kind not in ('water', 'cross') then return _no('space occupied', jsonb_build_object('cell', ocur)); end if;
  end if;
  inv := _give(me, w, it, -1, inv);
  update players set serial = serial + 1 where user_id = me and world = w returning serial into s;
  ch := ch || _set(w, px, py, pz, bid, me, pl.name, s);
  if rb.kind = 'door' then ch := ch || _set(w, px, py + 1, pz, bid + 1, me, pl.name, s);
  elsif rb.kind like 'bed%f' then ch := ch || _set(w, px + odx, py, pz + odz, bid + 4, me, pl.name, s);
  end if;
  if bid = 13 then
    stats := _validator_stats('common', 1);
    insert into validators (world, x, y, z, owner, owner_name, state, rarity, level, gwei_per_cycle, maintenance_cost, reanimated_at, last_cycle_at)
      values (w, px, py, pz, me, pl.name, 'active', 'common', 1, (stats ->> 'gwei_per_cycle')::int, (stats ->> 'maintenance_cost')::int, now(), now())
      on conflict (world, x, y, z) do update set owner = excluded.owner, owner_name = excluded.owner_name, state = 'active',
        rarity = 'common', level = 1, gwei_per_cycle = excluded.gwei_per_cycle, maintenance_cost = excluded.maintenance_cost,
        missed_cycles = 0, reanimated_at = now(), last_cycle_at = now();
  end if;
  return jsonb_build_object('ok', true, 'changes', ch, 'inv', inv, 'serial', s);
end $$;

-- Recovery (001_schema.sql) must also hand over owned validators, or they'd stay stuck on the old
-- account's uuid after a code recovery.
create or replace function public._core_claim_recovery(code text) returns integer
language plpgsql security definer set search_path = public, extensions as $$
declare old uuid; me uuid := auth.uid(); n integer;
begin
  if me is null then raise exception 'not signed in'; end if;
  select user_id into old from public.recovery where code_hash = encode(extensions.digest(upper(trim(code)), 'sha256'), 'hex');
  if old is null then raise exception 'unknown code'; end if;
  if old = me then return 0; end if;
  -- this device's account steps aside for the code's account, world by world
  delete from public.inventory i where i.user_id = me and exists (select 1 from public.players o where o.user_id = old and o.world = i.world);
  delete from public.uniques u where u.user_id = me and exists (select 1 from public.players o where o.user_id = old and o.world = u.world);
  delete from public.players p where p.user_id = me and exists (select 1 from public.players o where o.user_id = old and o.world = p.world);
  update public.players set user_id = me where user_id = old;
  get diagnostics n = row_count;
  update public.inventory set user_id = me where user_id = old;
  update public.uniques set user_id = me where user_id = old;
  update public.blocks set placed_by = me::text where placed_by = old::text;
  update public.claims set owner = me where owner = old;
  update public.claims set members = array_replace(members, old, me) where old = any (members);
  update public.validators set owner = me where owner = old;
  delete from public.recovery where user_id = me;
  update public.recovery set user_id = me where user_id = old;
  return n;
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 021_gwei_cycle_and_maintenance.sql ════════════════
-- 021: the validator production loop. A cycle is 5 minutes. Production and upkeep (gwei_per_cycle -
-- maintenance_cost net) are paid for every elapsed cycle regardless of attestation — a validator keeps
-- running in the background whether or not its operator is watching, so neglect never claws back Gwei
-- already earned. Attestation (act_maintain_validator) is a separate, independent health check: go more
-- than 24h without one and the validator degrades active -> damaged -> corrupted after 3/8 such cycles
-- (corrupted needs a Validator Heart to repair) — a daily check-in avoids that entirely. Ticking is lazy
-- (like the old rewards_at), never a background job: settled on attest and on the periodic "collect all"
-- (act_rewards, now paying Gwei instead of Ether Crystal). Attesting has no reach check, unlike
-- mining/placing/relighting: a real Ethereum validator attests over the network, not by being physically
-- near anything, so the fiction holds up fine without it — and it would otherwise force a player with
-- validators scattered around the world back to each one just to keep them running.
-- Requires 001_schema.sql, 002_security.sql, 019_gwei_currency.sql, 020_validators.sql. Replayable without error.

create or replace function public._tick_validator(w text, vid bigint) returns validators
language plpgsql security definer set search_path = public as $$
declare v validators; cycles int; maintained boolean; net int;
begin
  select * into v from validators where id = vid and world = w for update;
  if not found or v.state = 'dormant' or v.owner is null or v.last_cycle_at is null then return v; end if;
  cycles := floor(least(extract(epoch from now() - v.last_cycle_at), 86400) / 300)::int; -- 24h catch-up cap, 300s = 1 cycle
  if cycles <= 0 then return v; end if;
  -- production is always paid for elapsed cycles, whether or not the player checked in: the validator
  -- itself doesn't stop working. Only the health check (missed_cycles / degradation) below is gated on
  -- having actually attested in the last 24h.
  net := greatest(v.gwei_per_cycle - v.maintenance_cost, 0) * cycles;
  if net > 0 then perform _gwei(v.owner, w, net); end if;
  -- maintained = attested within the last 24h, counting back from now (not from last_cycle_at, which
  -- would let one attestation count as "maintained" forever if nobody ever ticks again)
  maintained := v.last_attested_at is not null and v.last_attested_at >= now() - interval '24 hours';
  if maintained then
    update validators set last_cycle_at = last_cycle_at + make_interval(secs => cycles * 300), missed_cycles = 0
      where id = vid returning * into v;
  else
    update validators set last_cycle_at = last_cycle_at + make_interval(secs => cycles * 300),
      missed_cycles = missed_cycles + cycles,
      state = case when missed_cycles + cycles >= 8 then 'corrupted' when missed_cycles + cycles >= 3 then 'damaged' else state end
      where id = vid returning * into v;
  end if;
  return v;
end $$;

-- Attest: settles any catch-up, then resets the clock. Free from "damaged"; from "corrupted" it costs
-- a Validator Heart (item 105), the same resource a fresh reanimation needs.
create or replace function public._core_maintain_validator(w text, validator_id bigint) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); v validators; inv jsonb := '{}';
begin
  perform _player(me, w);
  select * into v from validators where id = validator_id and world = w;
  if not found then return _no('unknown validator'); end if;
  if v.owner <> me then return _no('not your validator'); end if;
  if v.state = 'dormant' then return _no('this validator is dormant: reanimate it first'); end if;
  v := _tick_validator(w, validator_id);
  if v.state = 'corrupted' then
    if _count(me, w, 105) < 1 then return _no('corrupted: needs a validator heart to repair'); end if;
    inv := _give(me, w, 105, -1, inv);
  end if;
  update validators set state = 'active', missed_cycles = 0, last_attested_at = now() where id = validator_id returning * into v;
  return jsonb_build_object('ok', true, 'inv', inv, 'validator', row_to_json(v), 'gwei', _gwei_balance(me, w));
end $$;

-- The 5-argument version (ex/ey/ez for a reach check) predates this: CREATE OR REPLACE can't change a
-- function's parameter list, so the old overload needs dropping explicitly or it lingers alongside this one.
drop function if exists public.act_maintain_validator(text, bigint, real, real, real);
create or replace function public.act_maintain_validator(w text, validator_id bigint) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w);
begin
  if not _rate(me, 'maintain_validator', 0.3, 3) then return _no('too many actions'); end if;
  return _core_maintain_validator(w, validator_id);
end $$;

-- Upgrade: 50 * current level Gwei, caps at level 10, refuses while corrupted (repair first).
create or replace function public._core_upgrade_validator(w text, validator_id bigint) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); v validators; cost bigint; stats jsonb;
begin
  perform _player(me, w);
  select * into v from validators where id = validator_id and world = w;
  if not found then return _no('unknown validator'); end if;
  if v.owner <> me then return _no('not your validator'); end if;
  if v.state = 'dormant' then return _no('this validator is dormant: reanimate it first'); end if;
  if v.state = 'corrupted' then return _no('repair it first'); end if;
  if v.level >= 10 then return _no('already at maximum level'); end if;
  cost := 50 * v.level;
  if _gwei_balance(me, w) < cost then return _no('not enough gwei', jsonb_build_object('need', cost)); end if;
  stats := _validator_stats(v.rarity, v.level + 1);
  perform _gwei(me, w, -cost);
  update validators set level = v.level + 1, gwei_per_cycle = (stats ->> 'gwei_per_cycle')::int,
      maintenance_cost = (stats ->> 'maintenance_cost')::int
    where id = validator_id returning * into v;
  return jsonb_build_object('ok', true, 'validator', row_to_json(v), 'gwei', _gwei_balance(me, w), 'cost', cost);
end $$;

create or replace function public.act_upgrade_validator(w text, validator_id bigint) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w);
begin
  if not _rate(me, 'upgrade_validator', 0.2, 2) then return _no('too many actions'); end if;
  return _core_upgrade_validator(w, validator_id);
end $$;

-- "Collect all": ticks every validator the caller owns and reports the total Gwei gained. act_rewards
-- keeps its name, rate limit, and client call site (it used to pay Ether Crystal); only the body changes.
create or replace function public._core_rewards(w text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); pl players; before bigint; after bigint; n int := 0; vid bigint;
begin
  pl := _player(me, w);
  before := pl.gwei;
  for vid in select id from validators where world = w and owner = me and state <> 'dormant' loop
    perform _tick_validator(w, vid);
    n := n + 1;
  end loop;
  select gwei into after from players where user_id = me and world = w;
  return jsonb_build_object('ok', true, 'inv', '{}'::jsonb, 'gwei', after, 'gained', after - before, 'n', n);
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 022_cosmetics.sql ════════════════
-- 022: cosmetics, purchasable with Gwei. Purely decorative: never a combat, speed, harvest, or access
-- effect. Catalog filled in by supabase/rules.sql (rules.js's COSMETICS, see tools/rules.mjs), same
-- pattern as rule_blocks/rule_items/rule_recipes. A "block" category cosmetic also grants some units of
-- an existing decorative-only block (grant_item/grant_qty) instead of just flipping an ownership flag.
-- Requires 001_schema.sql, 019_gwei_currency.sql. Replayable without error.

create table if not exists public.rule_cosmetics (
  id         smallint primary key,
  name       text     not null,
  price      integer  not null,
  category   text     not null,
  grant_item smallint,
  grant_qty  integer
);
alter table public.rule_cosmetics enable row level security;
drop policy if exists "read rule_cosmetics" on public.rule_cosmetics;
create policy "read rule_cosmetics" on public.rule_cosmetics for select using (true);

create table if not exists public.cosmetics_owned (
  user_id     uuid        not null references auth.users (id) on delete cascade,
  world       text        not null,
  cosmetic_id smallint    not null,
  acquired_at timestamptz not null default now(),
  primary key (user_id, world, cosmetic_id)
);
alter table public.cosmetics_owned enable row level security;
drop policy if exists "read own cosmetics" on public.cosmetics_owned;
create policy "read own cosmetics" on public.cosmetics_owned for select to authenticated using (auth.uid() = user_id);

create or replace function public._core_buy_cosmetic(w text, cid int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); rc rule_cosmetics; inv jsonb := '{}';
begin
  perform _player(me, w);
  select * into rc from rule_cosmetics where id = cid;
  if not found then return _no('unknown cosmetic'); end if;
  if exists (select 1 from cosmetics_owned where user_id = me and world = w and cosmetic_id = rc.id) then
    return _no('already owned');
  end if;
  if _gwei_balance(me, w) < rc.price then return _no('not enough gwei', jsonb_build_object('need', rc.price)); end if;
  perform _gwei(me, w, -rc.price);
  insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, rc.id);
  if rc.grant_item is not null then inv := _give(me, w, rc.grant_item, coalesce(rc.grant_qty, 1), inv); end if;
  return jsonb_build_object('ok', true, 'cosmetic', rc.id, 'inv', inv, 'gwei', _gwei_balance(me, w));
end $$;

create or replace function public.act_buy_cosmetic(w text, cosmetic_id int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w);
begin
  if not _rate(me, 'buy_cosmetic', 0.3, 5) then return _no('too many actions'); end if;
  return _core_buy_cosmetic(w, cosmetic_id);
end $$;

-- Recovery (001_schema.sql, extended in 020_validators.sql) must also hand over owned cosmetics.
create or replace function public._core_claim_recovery(code text) returns integer
language plpgsql security definer set search_path = public, extensions as $$
declare old uuid; me uuid := auth.uid(); n integer;
begin
  if me is null then raise exception 'not signed in'; end if;
  select user_id into old from public.recovery where code_hash = encode(extensions.digest(upper(trim(code)), 'sha256'), 'hex');
  if old is null then raise exception 'unknown code'; end if;
  if old = me then return 0; end if;
  -- this device's account steps aside for the code's account, world by world
  delete from public.inventory i where i.user_id = me and exists (select 1 from public.players o where o.user_id = old and o.world = i.world);
  delete from public.uniques u where u.user_id = me and exists (select 1 from public.players o where o.user_id = old and o.world = u.world);
  delete from public.cosmetics_owned c where c.user_id = me and exists (select 1 from public.players o where o.user_id = old and o.world = c.world);
  delete from public.players p where p.user_id = me and exists (select 1 from public.players o where o.user_id = old and o.world = p.world);
  update public.players set user_id = me where user_id = old;
  get diagnostics n = row_count;
  update public.inventory set user_id = me where user_id = old;
  update public.uniques set user_id = me where user_id = old;
  update public.cosmetics_owned set user_id = me where user_id = old;
  update public.blocks set placed_by = me::text where placed_by = old::text;
  update public.claims set owner = me where owner = old;
  update public.claims set members = array_replace(members, old, me) where old = any (members);
  update public.validators set owner = me where owner = old;
  delete from public.recovery where user_id = me;
  update public.recovery set user_id = me where user_id = old;
  return n;
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 023_remove_onchain.sql ════════════════
-- 023: removes the real-blockchain layer from the database (supersedes 009_onchain_wallet.sql's tables
-- and function — never edit a published migration, add a new one). Sequenced after 020_validators.sql,
-- whose seal (item 203) now points at a validators row via uniques.validator_id instead of vx/vy/vz:
-- nothing reads the chain-era columns anymore, so they can go. Ether Mines no longer links a wallet,
-- calls an RPC, or mints/attests/claims on a real chain; see legacy/ for the archived contracts and
-- Edge Functions. Requires 001_schema.sql, 009_onchain_wallet.sql, 020_validators.sql.

drop function if exists public.act_wallet_nonce();
drop table if exists public.wallet_nonces;
drop table if exists public.wallets;

alter table public.uniques
  drop column if exists vx,
  drop column if exists vy,
  drop column if exists vz,
  drop column if exists chain_tx,
  drop column if exists token_id;

-- ════════════════ 024_loot_tiers.sql ════════════════
-- 024: loot tiers for regular (non-boss) mob kills. Layers two chances on top of the existing
-- resource-chance table instead of replacing it: a rare tier (Gwei, a direct link between combat and
-- the off-chain economy) and an epic tier (a combat-exclusive cosmetic, never sold in the shop). Boss
-- kills (titan, plasma_core) are untouched — their guaranteed trophy is already the legendary tier.
-- Requires 001_schema.sql, 002_security.sql, 013_mob_loot.sql..018_more_mob_loot.sql,
-- 019_gwei_currency.sql, 022_cosmetics.sql. Replayable without error.

create or replace function public.act_loot_mob(w text, mob_type text, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); e text; it int; inv jsonb := '{}'; r real; u jsonb; cid smallint; g int;
begin
  if mob_type in ('titan', 'plasma_core') then
    if not _rate(me, 'loot_boss', 0.05, 1) then return _no('too many actions'); end if;
    e := _check_pos(me, w, ex, ey, ez);
    if e is not null then return _no(e); end if;
    u := _mint(me, w, case when mob_type = 'titan' then 205 else 206 end, null);
    return jsonb_build_object('ok', true, 'inv', inv, 'unique', u);
  end if;
  if not _rate(me, 'loot_mob', 0.2, 5) then return _no('too many actions'); end if;
  e := _check_pos(me, w, ex, ey, ez);
  if e is not null then return _no(e); end if;
  -- epic (~3%): a combat-exclusive cosmetic the player doesn't already own; falls through to the
  -- common table once every combat cosmetic is collected. rare (~12%): a small Gwei bonus.
  r := random();
  if r < 0.03 then
    select id into cid from rule_cosmetics where category = 'combat'
      and id not in (select cosmetic_id from cosmetics_owned where user_id = me and world = w)
      order by random() limit 1;
    if cid is not null then
      insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, cid);
      return jsonb_build_object('ok', true, 'inv', inv, 'cosmetic', cid);
    end if;
  elsif r < 0.15 then
    g := 10 + floor(random() * 41)::int; -- 10..50
    perform _gwei(me, w, g);
    return jsonb_build_object('ok', true, 'inv', inv, 'gwei', g, 'total_gwei', _gwei_balance(me, w));
  end if;
  -- common (unchanged): the existing per-mob-type resource chance, its own independent roll
  r := random();
  it := case mob_type
    when 'shadow' then case when r < 0.5 then 101 end
    when 'guardian' then case when r < 0.35 then 101 when r < 0.5 then 103 end
    when 'sentinel' then case when r < 0.4 then 103 end
    when 'wraith' then case when r < 0.25 then 104 when r < 0.65 then 103 end
    when 'warden' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'garden_guardian' then case when r < 0.35 then 101 when r < 0.5 then 103 end
    when 'prowler' then case when r < 0.5 then 101 end
    when 'sky_raider' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'water_lurker' then case when r < 0.25 then 103 when r < 0.5 then 104 end
    when 'bat' then case when r < 0.45 then 101 end
    when 'crawler' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'golem' then case when r < 0.3 then 103 when r < 0.55 then 104 end
    else null
  end;
  if it is null then return jsonb_build_object('ok', true, 'inv', inv); end if;
  inv := _give(me, w, it, 1, inv);
  return jsonb_build_object('ok', true, 'inv', inv, 'item', it);
end $$;

-- combat-exclusive cosmetics are never for sale, even by calling act_buy_cosmetic with their id directly.
create or replace function public._core_buy_cosmetic(w text, cid int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); rc rule_cosmetics; inv jsonb := '{}';
begin
  perform _player(me, w);
  select * into rc from rule_cosmetics where id = cid;
  if not found then return _no('unknown cosmetic'); end if;
  if rc.category = 'combat' then return _no('not for sale'); end if;
  if exists (select 1 from cosmetics_owned where user_id = me and world = w and cosmetic_id = rc.id) then
    return _no('already owned');
  end if;
  if _gwei_balance(me, w) < rc.price then return _no('not enough gwei', jsonb_build_object('need', rc.price)); end if;
  perform _gwei(me, w, -rc.price);
  insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, rc.id);
  if rc.grant_item is not null then inv := _give(me, w, rc.grant_item, coalesce(rc.grant_qty, 1), inv); end if;
  return jsonb_build_object('ok', true, 'cosmetic', rc.id, 'inv', inv, 'gwei', _gwei_balance(me, w));
end $$;

-- ════════════════ 025_tower_treasure.sql ════════════════
-- 025: a treasure chest atop every tower (world.js GEN 19), seeded with better-than-average loot the
-- first time it's opened. Distinguishing a tower's chest from a player-placed one: the tower's comes
-- straight from the generator, so it has no blocks override row for that cell — a player-placed chest
-- always does (act_place writes one). Requires 001_schema.sql, 002_security.sql, 004_chests.sql.
-- Replayable without error.

create or replace function public._seed_tower_chest(w text, px int, py int, pz int) returns void
language plpgsql security definer set search_path = public as $$
begin
  if exists (select 1 from chests where world = w and x = px and y = py and z = pz) then return; end if;
  if exists (select 1 from blocks where world = w and x = px and y = py and z = pz) then return; end if;
  insert into chests (world, x, y, z, items) values (w, px, py, pz,
    jsonb_build_object('101', 15 + floor(random() * 11)::int, '103', 4 + floor(random() * 5)::int) -- 15-25 crystals, 4-8 pure shards
      || case when random() < 0.5 then jsonb_build_object('104', 1) else '{}'::jsonb end)           -- 50% bonus genesis fragment
    on conflict do nothing;
end $$;

create or replace function public.act_chest(w text, px int, py int, pz int, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); e text := _chest_ok(me, w, px, py, pz, ex, ey, ez);
begin
  if e is not null then return _no(e); end if;
  perform _seed_tower_chest(w, px, py, pz);
  return jsonb_build_object('ok', true, 'items',
    coalesce((select items from chests where world = w and x = px and y = py and z = pz), '{}'::jsonb));
end $$;

create or replace function public.act_chest_move(w text, px int, py int, pz int, item int, n int, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); e text := _chest_ok(me, w, px, py, pz, ex, ey, ez);
        cur jsonb; have int; inv jsonb := '{}'::jsonb;
begin
  if e is not null then return _no(e); end if;
  if n = 0 or abs(n) > 10000 then return _no('invalid quantity'); end if;
  perform _seed_tower_chest(w, px, py, pz);
  insert into chests (world, x, y, z) values (w, px, py, pz) on conflict do nothing;
  select items into cur from chests where world = w and x = px and y = py and z = pz for update;
  if cur is null or _cell(w, px, py, pz) <> 98 then return _no('no chest here'); end if;
  have := coalesce((cur ->> item::text)::int, 0);
  if n > 0 then
    if _count(me, w, item) < n then return _no('not enough in your bag'); end if;
    if have = 0 and (select count(*) from jsonb_object_keys(cur)) >= 27 then return _no('chest full'); end if;
    inv := _give(me, w, item, -n, inv);
    cur := cur || jsonb_build_object(item::text, have + n);
  else
    n := greatest(n, -have);
    if n = 0 then return _no('none of that item in the chest'); end if;
    inv := _give(me, w, item, -n, inv);
    cur := case when have + n = 0 then cur - item::text else cur || jsonb_build_object(item::text, have + n) end;
  end if;
  update chests set items = cur where world = w and x = px and y = py and z = pz;
  return jsonb_build_object('ok', true, 'items', cur, 'inv', inv);
end $$;

-- ════════════════ 026_boss_bonus_trophies.sql ════════════════
-- 026: a second, rarer bonus trophy on boss kills. Titan and plasma_core already guarantee their main
-- trophy every time (015/016_*.sql); this layers an independent ~20% chance of a second, purely
-- cosmetic unique (never traded, same nft:1 convention) on top — a reason to keep farming a boss beyond
-- the first kill. Requires 001_schema.sql, 002_security.sql, 013_mob_loot.sql..018_more_mob_loot.sql,
-- 024_loot_tiers.sql. Replayable without error.

create or replace function public.act_loot_mob(w text, mob_type text, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); e text; it int; inv jsonb := '{}'; r real; u jsonb; cid smallint; g int; bonus jsonb;
begin
  if mob_type in ('titan', 'plasma_core') then
    if not _rate(me, 'loot_boss', 0.05, 1) then return _no('too many actions'); end if;
    e := _check_pos(me, w, ex, ey, ez);
    if e is not null then return _no(e); end if;
    u := _mint(me, w, case when mob_type = 'titan' then 205 else 206 end, null);
    if random() < 0.2 then
      bonus := _mint(me, w, case when mob_type = 'titan' then 207 else 208 end, null);
    end if;
    return jsonb_build_object('ok', true, 'inv', inv, 'unique', u, 'bonus', bonus);
  end if;
  if not _rate(me, 'loot_mob', 0.2, 5) then return _no('too many actions'); end if;
  e := _check_pos(me, w, ex, ey, ez);
  if e is not null then return _no(e); end if;
  -- epic (~3%): a combat-exclusive cosmetic the player doesn't already own; falls through to the
  -- common table once every combat cosmetic is collected. rare (~12%): a small Gwei bonus.
  r := random();
  if r < 0.03 then
    select id into cid from rule_cosmetics where category = 'combat'
      and id not in (select cosmetic_id from cosmetics_owned where user_id = me and world = w)
      order by random() limit 1;
    if cid is not null then
      insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, cid);
      return jsonb_build_object('ok', true, 'inv', inv, 'cosmetic', cid);
    end if;
  elsif r < 0.15 then
    g := 10 + floor(random() * 41)::int; -- 10..50
    perform _gwei(me, w, g);
    return jsonb_build_object('ok', true, 'inv', inv, 'gwei', g, 'total_gwei', _gwei_balance(me, w));
  end if;
  -- common (unchanged): the existing per-mob-type resource chance, its own independent roll
  r := random();
  it := case mob_type
    when 'shadow' then case when r < 0.5 then 101 end
    when 'guardian' then case when r < 0.35 then 101 when r < 0.5 then 103 end
    when 'sentinel' then case when r < 0.4 then 103 end
    when 'wraith' then case when r < 0.25 then 104 when r < 0.65 then 103 end
    when 'warden' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'garden_guardian' then case when r < 0.35 then 101 when r < 0.5 then 103 end
    when 'prowler' then case when r < 0.5 then 101 end
    when 'sky_raider' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'water_lurker' then case when r < 0.25 then 103 when r < 0.5 then 104 end
    when 'bat' then case when r < 0.45 then 101 end
    when 'crawler' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'golem' then case when r < 0.3 then 103 when r < 0.55 then 104 end
    else null
  end;
  if it is null then return jsonb_build_object('ok', true, 'inv', inv); end if;
  inv := _give(me, w, it, 1, inv);
  return jsonb_build_object('ok', true, 'inv', inv, 'item', it);
end $$;

-- ════════════════ 027_network_attack.sql ════════════════
-- 027: the network attack event. Every real-world hour, for its first 10 minutes, a wave of corrupted
-- nodes converges on the Atrium (SPAWN, 8/8) — src/game/16-mobs.js spawns them client-side the same
-- deterministic way every other mob already works (no server presence, no realtime: every client
-- independently computes the same wall-clock window). Only kills are reported here, the same bounded,
-- rate-limited, position-checked trust act_loot_mob already extends to every other mob type.
-- Requires 001_schema.sql, 002_security.sql, 007_network.sql, 013_mob_loot.sql..018_more_mob_loot.sql,
-- 019_gwei_currency.sql, 022_cosmetics.sql, 024_loot_tiers.sql, 026_boss_bonus_trophies.sql.
-- Replayable without error.

-- Pure function of a timestamp (defaults to now()): which hourly window it falls in, whether that
-- window is still in its first 10 minutes, and when it closes. Parameterized so tests can assert both
-- sides of the boundary with a fixed timestamp instead of depending on whatever time the suite runs at.
create or replace function public._attack_window(ts timestamptz default now())
returns table(window_id bigint, active boolean, ends_at timestamptz)
language sql immutable as $$
  select floor(extract(epoch from ts) / 3600)::bigint,
         (extract(epoch from ts)::bigint % 3600) < 600,
         to_timestamp(floor(extract(epoch from ts) / 3600)::bigint * 3600 + 600)
$$;

create table if not exists public.network_events (
  world        text    not null,
  window_id    bigint  not null,
  kills        int     not null default 0,
  participants jsonb   not null default '{}', -- {user_id: kill_count}, read once at resolution to pay out
  resolved     boolean not null default false,
  primary key (world, window_id)
);
alter table public.network_events enable row level security; -- no policy: functions only

create table if not exists public.network_score (
  world              text primary key,
  score              int    not null default 0, -- running total, never resets; drives the diamond's tier
  last_resolved_window bigint not null default 0
);
alter table public.network_score enable row level security;
drop policy if exists "read network_score" on public.network_score;
create policy "read network_score" on public.network_score for select using (true); -- world-wide score, visible like blocks/claims

-- Resolves every closed window since the last one checked, including windows nobody touched at all (no
-- network_events row — "no punishment for nobody's timezone," a small score tick happens either way).
-- Capped at the last 24 windows, same spirit as _tick_validator's 24h catch-up cap. Below the 20-kill
-- threshold (including 0): +1 score, no individual payout. At or above it: +10 score, and every
-- contributor gets 50 Gwei plus, the first time ever, the defenders' cosmetic.
create or replace function public._resolve_attack_windows(w text) returns void
language plpgsql security definer set search_path = public as $$
declare cur bigint; from_w bigint; wid bigint; ev network_events; uid text; cid smallint;
begin
  select (_attack_window()).window_id into cur;
  insert into network_score (world) values (w) on conflict do nothing;
  select last_resolved_window into from_w from network_score where world = w for update;
  from_w := greatest(from_w, cur - 24);
  for wid in from_w + 1 .. cur - 1 loop
    select * into ev from network_events where world = w and window_id = wid;
    if found and not ev.resolved then
      if ev.kills >= 20 then
        update network_score set score = score + 10 where world = w;
        for uid in select jsonb_object_keys(ev.participants) loop
          perform _gwei(uid::uuid, w, 50);
          select id into cid from rule_cosmetics where category = 'event' limit 1;
          if cid is not null then
            insert into cosmetics_owned (user_id, world, cosmetic_id) values (uid::uuid, w, cid) on conflict do nothing;
          end if;
        end loop;
      else
        update network_score set score = score + 1 where world = w;
      end if;
      update network_events set resolved = true where world = w and window_id = wid;
    elsif not found then
      update network_score set score = score + 1 where world = w;
    end if;
  end loop;
  update network_score set last_resolved_window = cur - 1 where world = w and cur - 1 > last_resolved_window;
end $$;

create or replace function public.act_network(w text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); total int; top jsonb; aw record; sc int; kl int;
begin
  if not _rate(me, 'network', 0.2, 5) then return _no('too many actions'); end if;
  perform _resolve_attack_windows(w);
  select count(*) into total from blocks where world = w and id = 74;
  select coalesce(jsonb_agg(jsonb_build_object('name', t.name, 'n', t.c) order by t.c desc, t.name), '[]'::jsonb) into top
    from (select coalesce(max(placed_name), 'anonymous') as name, count(*) as c from blocks
           where world = w and id = 74 group by placed_by order by count(*) desc limit 5) t;
  select * into aw from _attack_window();
  select score into sc from network_score where world = w;
  select kills into kl from network_events where world = w and window_id = aw.window_id;
  return jsonb_build_object('ok', true, 'n', total, 'top', top, 'attack', jsonb_build_object(
    'window_id', aw.window_id, 'active', aw.active, 'ends_at', aw.ends_at,
    'kills', coalesce(kl, 0), 'score', coalesce(sc, 0)));
end $$;

-- corrupted nodes: only during the attack window, only near the Atrium. Its own rate-limit bucket
-- ('attack_node') so grinding the event can't be throttled by, or used to bypass, regular mob loot.
create or replace function public.act_loot_mob(w text, mob_type text, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); e text; it int; inv jsonb := '{}'; r real; u jsonb; cid smallint; g int; bonus jsonb; aw record;
begin
  if mob_type = 'corrupted_node' then
    if not _rate(me, 'attack_node', 0.3, 6) then return _no('too many actions'); end if;
    e := _check_pos(me, w, ex, ey, ez);
    if e is not null then return _no(e); end if;
    if sqrt((ex - 8) ^ 2 + (ez - 8) ^ 2) > 30 then return _no('too far from the Atrium'); end if;
    select * into aw from _attack_window();
    if not aw.active then return _no('no attack right now'); end if;
    insert into network_events (world, window_id, kills, participants) values (w, aw.window_id, 1, jsonb_build_object(me::text, 1))
      on conflict (world, window_id) do update set kills = network_events.kills + 1,
        participants = network_events.participants || jsonb_build_object(me::text, coalesce((network_events.participants ->> me::text)::int, 0) + 1);
    r := random();
    if r < 0.08 then
      select id into cid from rule_cosmetics where category = 'event'
        and id not in (select cosmetic_id from cosmetics_owned where user_id = me and world = w) order by random() limit 1;
      if cid is not null then
        insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, cid);
        return jsonb_build_object('ok', true, 'inv', inv, 'cosmetic', cid);
      end if;
    elsif r < 0.33 then
      g := 10 + floor(random() * 41)::int;
      perform _gwei(me, w, g);
      return jsonb_build_object('ok', true, 'inv', inv, 'gwei', g, 'total_gwei', _gwei_balance(me, w));
    end if;
    inv := _give(me, w, 101, 1 + floor(random() * 2)::int, inv); -- no whiffed kills during the event: a guaranteed small bundle
    return jsonb_build_object('ok', true, 'inv', inv);
  end if;
  if mob_type in ('titan', 'plasma_core') then
    if not _rate(me, 'loot_boss', 0.05, 1) then return _no('too many actions'); end if;
    e := _check_pos(me, w, ex, ey, ez);
    if e is not null then return _no(e); end if;
    u := _mint(me, w, case when mob_type = 'titan' then 205 else 206 end, null);
    if random() < 0.2 then
      bonus := _mint(me, w, case when mob_type = 'titan' then 207 else 208 end, null);
    end if;
    return jsonb_build_object('ok', true, 'inv', inv, 'unique', u, 'bonus', bonus);
  end if;
  if not _rate(me, 'loot_mob', 0.2, 5) then return _no('too many actions'); end if;
  e := _check_pos(me, w, ex, ey, ez);
  if e is not null then return _no(e); end if;
  -- epic (~3%): a combat-exclusive cosmetic the player doesn't already own; falls through to the
  -- common table once every combat cosmetic is collected. rare (~12%): a small Gwei bonus.
  r := random();
  if r < 0.03 then
    select id into cid from rule_cosmetics where category = 'combat'
      and id not in (select cosmetic_id from cosmetics_owned where user_id = me and world = w)
      order by random() limit 1;
    if cid is not null then
      insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, cid);
      return jsonb_build_object('ok', true, 'inv', inv, 'cosmetic', cid);
    end if;
  elsif r < 0.15 then
    g := 10 + floor(random() * 41)::int; -- 10..50
    perform _gwei(me, w, g);
    return jsonb_build_object('ok', true, 'inv', inv, 'gwei', g, 'total_gwei', _gwei_balance(me, w));
  end if;
  -- common (unchanged): the existing per-mob-type resource chance, its own independent roll
  r := random();
  it := case mob_type
    when 'shadow' then case when r < 0.5 then 101 end
    when 'guardian' then case when r < 0.35 then 101 when r < 0.5 then 103 end
    when 'sentinel' then case when r < 0.4 then 103 end
    when 'wraith' then case when r < 0.25 then 104 when r < 0.65 then 103 end
    when 'warden' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'garden_guardian' then case when r < 0.35 then 101 when r < 0.5 then 103 end
    when 'prowler' then case when r < 0.5 then 101 end
    when 'sky_raider' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'water_lurker' then case when r < 0.25 then 103 when r < 0.5 then 104 end
    when 'bat' then case when r < 0.45 then 101 end
    when 'crawler' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'golem' then case when r < 0.3 then 103 when r < 0.55 then 104 end
    else null
  end;
  if it is null then return jsonb_build_object('ok', true, 'inv', inv); end if;
  inv := _give(me, w, it, 1, inv);
  return jsonb_build_object('ok', true, 'inv', inv, 'item', it);
end $$;

-- event cosmetics (same shape as combat ones, 024_loot_tiers.sql): never for sale either.
create or replace function public._core_buy_cosmetic(w text, cid int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); rc rule_cosmetics; inv jsonb := '{}';
begin
  perform _player(me, w);
  select * into rc from rule_cosmetics where id = cid;
  if not found then return _no('unknown cosmetic'); end if;
  if rc.category in ('combat', 'event') then return _no('not for sale'); end if;
  if exists (select 1 from cosmetics_owned where user_id = me and world = w and cosmetic_id = rc.id) then
    return _no('already owned');
  end if;
  if _gwei_balance(me, w) < rc.price then return _no('not enough gwei', jsonb_build_object('need', rc.price)); end if;
  perform _gwei(me, w, -rc.price);
  insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, rc.id);
  if rc.grant_item is not null then inv := _give(me, w, rc.grant_item, coalesce(rc.grant_qty, 1), inv); end if;
  return jsonb_build_object('ok', true, 'cosmetic', rc.id, 'inv', inv, 'gwei', _gwei_balance(me, w));
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 028_leaderboard.sql ════════════════
-- 028: a world-visible leaderboard — Gwei earned, validators kept active, attacks repelled — rendered
-- on a monument in the City (src/game/04-render.js) instead of buried in a tab. Same poll-and-render
-- shape as the network's own shared-goal panel; the three numbers below are just new angles on data
-- that already exists (Gwei, validators, 027_network_attack.sql's defenses) plus one new cumulative
-- counter (gwei_earned: spending never lowers your rank, only earning raises it).
-- Requires 001_schema.sql, 002_security.sql, 007_network.sql, 019_gwei_currency.sql,
-- 020_validators.sql, 027_network_attack.sql. Replayable without error.

alter table public.players add column if not exists gwei_earned bigint not null default 0;
alter table public.players add column if not exists defenses_won int not null default 0;

-- gwei_earned only ever grows: spending (d < 0) still updates the live balance, never the rank.
create or replace function public._gwei(me uuid, w text, d bigint) returns bigint
language plpgsql security definer set search_path = public as $$
declare v bigint;
begin
  update players set gwei = gwei + d, gwei_earned = gwei_earned + greatest(d, 0)
    where user_id = me and world = w returning gwei into v;
  if v is null or v < 0 then raise exception 'not enough gwei'; end if;
  return v;
end $$;

-- a successful defense also counts toward each contributor's own tally, not just the Gwei/cosmetic payout.
create or replace function public._resolve_attack_windows(w text) returns void
language plpgsql security definer set search_path = public as $$
declare cur bigint; from_w bigint; wid bigint; ev network_events; uid text; cid smallint;
begin
  select (_attack_window()).window_id into cur;
  insert into network_score (world) values (w) on conflict do nothing;
  select last_resolved_window into from_w from network_score where world = w for update;
  from_w := greatest(from_w, cur - 24);
  for wid in from_w + 1 .. cur - 1 loop
    select * into ev from network_events where world = w and window_id = wid;
    if found and not ev.resolved then
      if ev.kills >= 20 then
        update network_score set score = score + 10 where world = w;
        for uid in select jsonb_object_keys(ev.participants) loop
          perform _gwei(uid::uuid, w, 50);
          update players set defenses_won = defenses_won + 1 where user_id = uid::uuid and world = w;
          select id into cid from rule_cosmetics where category = 'event' limit 1;
          if cid is not null then
            insert into cosmetics_owned (user_id, world, cosmetic_id) values (uid::uuid, w, cid) on conflict do nothing;
          end if;
        end loop;
      else
        update network_score set score = score + 1 where world = w;
      end if;
      update network_events set resolved = true where world = w and window_id = wid;
    elsif not found then
      update network_score set score = score + 1 where world = w;
    end if;
  end loop;
  update network_score set last_resolved_window = cur - 1 where world = w and cur - 1 > last_resolved_window;
end $$;

create or replace function public.act_leaderboard(w text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); gwei_top jsonb; validators_top jsonb; defenses_top jsonb;
begin
  if not _rate(me, 'leaderboard', 0.1, 3) then return _no('too many actions'); end if;
  select coalesce(jsonb_agg(jsonb_build_object('name', t.name, 'n', t.gwei_earned) order by t.gwei_earned desc), '[]'::jsonb) into gwei_top
    from (select coalesce(name, 'anonymous') as name, gwei_earned from players
          where world = w and gwei_earned > 0 order by gwei_earned desc limit 5) t;
  select coalesce(jsonb_agg(jsonb_build_object('name', t.name, 'n', t.c) order by t.c desc, t.name), '[]'::jsonb) into validators_top
    from (select coalesce(max(owner_name), 'anonymous') as name, count(*) as c from validators
          where world = w and owner is not null and state in ('active', 'damaged') group by owner order by count(*) desc limit 5) t;
  select coalesce(jsonb_agg(jsonb_build_object('name', t.name, 'n', t.defenses_won) order by t.defenses_won desc), '[]'::jsonb) into defenses_top
    from (select coalesce(name, 'anonymous') as name, defenses_won from players
          where world = w and defenses_won > 0 order by defenses_won desc limit 5) t;
  return jsonb_build_object('ok', true, 'gwei', gwei_top, 'validators', validators_top, 'defenses', defenses_top);
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 029_chapters.sql ════════════════
-- 029: story chapters. The objectives are grouped into chapters (07-interface.js's CHAPTERS); finishing
-- one pays a Gwei reward and grants a title, a never-sold "title" cosmetic (rules.js COSMETICS 15-19).
-- Owning the title IS the "already claimed" marker: no new table, and account recovery (022) already
-- carries cosmetics_owned over. The client decides when a chapter is done (most objectives are client
-- flags), so the server only pays against proofs it can check itself — the chapter's key milestone —
-- never against the client's word alone.
-- Requires 001_schema.sql, 002_security.sql, 019_gwei_currency.sql, 020_validators.sql,
-- 022_cosmetics.sql, 027_network_attack.sql. Replayable without error.

create or replace function public._core_claim_chapter(w text, chapter text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); cid smallint; g int; proof boolean; nv int;
begin
  perform _player(me, w);
  select v.cid, v.g into cid, g from (values
    ('genesis', 15::smallint, 50), ('forge', 16::smallint, 100), ('awakening', 17::smallint, 200),
    ('network', 18::smallint, 400), ('circuits', 19::smallint, 100)) v(id, cid, g) where v.id = chapter;
  if cid is null then return _no('unknown chapter'); end if;
  if exists (select 1 from cosmetics_owned where user_id = me and world = w and cosmetic_id = cid) then
    return _no('already claimed');
  end if;
  select count(*) into nv from validators where world = w and owner = me;
  proof := case chapter
    -- a pickaxe of any tier: the chapter's tools were crafted
    when 'genesis' then exists (select 1 from inventory where user_id = me and world = w and item = 102 and n > 0)
                     or exists (select 1 from uniques where user_id = me and world = w and item in (201, 202))
    -- the pure ether pickaxe: the forge's last tool
    when 'forge' then exists (select 1 from uniques where user_id = me and world = w and item = 202)
    -- a validator relit (or placed) under your name
    when 'awakening' then nv >= 1
    -- three validators, both boss trophies, and a kill during a network attack
    when 'network' then nv >= 3
                     and exists (select 1 from uniques where user_id = me and world = w and item = 205)
                     and exists (select 1 from uniques where user_id = me and world = w and item = 206)
                     and exists (select 1 from network_events where world = w and participants ? me::text)
    -- an AND, an OR and a NOT gate standing in the world, placed by you
    when 'circuits' then (select count(distinct (id - 112) / 4) from blocks
                          where world = w and placed_by = me::text and id between 112 and 123) = 3
  end;
  if not proof then return _no('chapter not finished'); end if;
  insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, cid);
  perform _gwei(me, w, g);
  return jsonb_build_object('ok', true, 'cosmetic', cid, 'gwei', g, 'total_gwei', _gwei_balance(me, w));
end $$;

create or replace function public.act_claim_chapter(w text, chapter text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w);
begin
  if not _rate(me, 'claim_chapter', 0.2, 5) then return _no('too many actions'); end if;
  return _core_claim_chapter(w, chapter);
end $$;

-- titles are never sold either (same shape as 024's combat and 027's event cosmetics)
create or replace function public._core_buy_cosmetic(w text, cid int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); rc rule_cosmetics; inv jsonb := '{}';
begin
  perform _player(me, w);
  select * into rc from rule_cosmetics where id = cid;
  if not found then return _no('unknown cosmetic'); end if;
  if rc.category in ('combat', 'event', 'title') then return _no('not for sale'); end if;
  if exists (select 1 from cosmetics_owned where user_id = me and world = w and cosmetic_id = rc.id) then
    return _no('already owned');
  end if;
  if _gwei_balance(me, w) < rc.price then return _no('not enough gwei', jsonb_build_object('need', rc.price)); end if;
  perform _gwei(me, w, -rc.price);
  insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, rc.id);
  if rc.grant_item is not null then inv := _give(me, w, rc.grant_item, coalesce(rc.grant_qty, 1), inv); end if;
  return jsonb_build_object('ok', true, 'cosmetic', rc.id, 'inv', inv, 'gwei', _gwei_balance(me, w));
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 030_merge_twins.sql ════════════════
-- 030: the Merge Sanctum's twin bosses (mergeAt(), world.js; src/game/16-mobs.js). The client reports
-- one 'merge_twins' kill when both twins fall together; it pays like the other bosses: a guaranteed
-- unique (209, the Merge Aegis armor) and an independent ~20% bonus keepsake (210), sharing the
-- loot_boss rate limit with the Titan and the Plasma Core. The rest of act_loot_mob is 027's, unchanged.
-- The story chapter that goes with it (chapter 5, "The Merge") is paid by act_claim_chapter, proof: 209.
-- Requires 001_schema.sql, 002_security.sql, 024_loot_tiers.sql, 027_network_attack.sql, 029_chapters.sql.
-- Replayable without error.

create or replace function public.act_loot_mob(w text, mob_type text, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); e text; it int; inv jsonb := '{}'; r real; u jsonb; cid smallint; g int; bonus jsonb; aw record;
begin
  -- 030: the Merge twins, reported once, when both fall together — a guaranteed Merge Aegis, ~20% a bonus
  if mob_type = 'merge_twins' then
    if not _rate(me, 'loot_boss', 0.05, 1) then return _no('too many actions'); end if;
    e := _check_pos(me, w, ex, ey, ez);
    if e is not null then return _no(e); end if;
    u := _mint(me, w, 209, null);
    if random() < 0.2 then bonus := _mint(me, w, 210, null); end if;
    return jsonb_build_object('ok', true, 'inv', inv, 'unique', u, 'bonus', bonus);
  end if;
  if mob_type = 'corrupted_node' then
    if not _rate(me, 'attack_node', 0.3, 6) then return _no('too many actions'); end if;
    e := _check_pos(me, w, ex, ey, ez);
    if e is not null then return _no(e); end if;
    if sqrt((ex - 8) ^ 2 + (ez - 8) ^ 2) > 30 then return _no('too far from the Atrium'); end if;
    select * into aw from _attack_window();
    if not aw.active then return _no('no attack right now'); end if;
    insert into network_events (world, window_id, kills, participants) values (w, aw.window_id, 1, jsonb_build_object(me::text, 1))
      on conflict (world, window_id) do update set kills = network_events.kills + 1,
        participants = network_events.participants || jsonb_build_object(me::text, coalesce((network_events.participants ->> me::text)::int, 0) + 1);
    r := random();
    if r < 0.08 then
      select id into cid from rule_cosmetics where category = 'event'
        and id not in (select cosmetic_id from cosmetics_owned where user_id = me and world = w) order by random() limit 1;
      if cid is not null then
        insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, cid);
        return jsonb_build_object('ok', true, 'inv', inv, 'cosmetic', cid);
      end if;
    elsif r < 0.33 then
      g := 10 + floor(random() * 41)::int;
      perform _gwei(me, w, g);
      return jsonb_build_object('ok', true, 'inv', inv, 'gwei', g, 'total_gwei', _gwei_balance(me, w));
    end if;
    inv := _give(me, w, 101, 1 + floor(random() * 2)::int, inv); -- no whiffed kills during the event: a guaranteed small bundle
    return jsonb_build_object('ok', true, 'inv', inv);
  end if;
  if mob_type in ('titan', 'plasma_core') then
    if not _rate(me, 'loot_boss', 0.05, 1) then return _no('too many actions'); end if;
    e := _check_pos(me, w, ex, ey, ez);
    if e is not null then return _no(e); end if;
    u := _mint(me, w, case when mob_type = 'titan' then 205 else 206 end, null);
    if random() < 0.2 then
      bonus := _mint(me, w, case when mob_type = 'titan' then 207 else 208 end, null);
    end if;
    return jsonb_build_object('ok', true, 'inv', inv, 'unique', u, 'bonus', bonus);
  end if;
  if not _rate(me, 'loot_mob', 0.2, 5) then return _no('too many actions'); end if;
  e := _check_pos(me, w, ex, ey, ez);
  if e is not null then return _no(e); end if;
  -- epic (~3%): a combat-exclusive cosmetic the player doesn't already own; falls through to the
  -- common table once every combat cosmetic is collected. rare (~12%): a small Gwei bonus.
  r := random();
  if r < 0.03 then
    select id into cid from rule_cosmetics where category = 'combat'
      and id not in (select cosmetic_id from cosmetics_owned where user_id = me and world = w)
      order by random() limit 1;
    if cid is not null then
      insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, cid);
      return jsonb_build_object('ok', true, 'inv', inv, 'cosmetic', cid);
    end if;
  elsif r < 0.15 then
    g := 10 + floor(random() * 41)::int; -- 10..50
    perform _gwei(me, w, g);
    return jsonb_build_object('ok', true, 'inv', inv, 'gwei', g, 'total_gwei', _gwei_balance(me, w));
  end if;
  -- common (unchanged): the existing per-mob-type resource chance, its own independent roll
  r := random();
  it := case mob_type
    when 'shadow' then case when r < 0.5 then 101 end
    when 'guardian' then case when r < 0.35 then 101 when r < 0.5 then 103 end
    when 'sentinel' then case when r < 0.4 then 103 end
    when 'wraith' then case when r < 0.25 then 104 when r < 0.65 then 103 end
    when 'warden' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'garden_guardian' then case when r < 0.35 then 101 when r < 0.5 then 103 end
    when 'prowler' then case when r < 0.5 then 101 end
    when 'sky_raider' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'water_lurker' then case when r < 0.25 then 103 when r < 0.5 then 104 end
    when 'bat' then case when r < 0.45 then 101 end
    when 'crawler' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'golem' then case when r < 0.3 then 103 when r < 0.55 then 104 end
    else null
  end;
  if it is null then return jsonb_build_object('ok', true, 'inv', inv); end if;
  inv := _give(me, w, it, 1, inv);
  return jsonb_build_object('ok', true, 'inv', inv, 'item', it);
end $$;

-- chapter 5, The Merge: 600 Gwei and the Merge Keeper title, against the Merge Aegis
create or replace function public._core_claim_chapter(w text, chapter text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); cid smallint; g int; proof boolean; nv int;
begin
  perform _player(me, w);
  select v.cid, v.g into cid, g from (values
    ('genesis', 15::smallint, 50), ('forge', 16::smallint, 100), ('awakening', 17::smallint, 200),
    ('network', 18::smallint, 400), ('circuits', 19::smallint, 100), ('merge', 20::smallint, 600)) v(id, cid, g) where v.id = chapter;
  if cid is null then return _no('unknown chapter'); end if;
  if exists (select 1 from cosmetics_owned where user_id = me and world = w and cosmetic_id = cid) then
    return _no('already claimed');
  end if;
  select count(*) into nv from validators where world = w and owner = me;
  proof := case chapter
    -- a pickaxe of any tier: the chapter's tools were crafted
    when 'genesis' then exists (select 1 from inventory where user_id = me and world = w and item = 102 and n > 0)
                     or exists (select 1 from uniques where user_id = me and world = w and item in (201, 202))
    -- the pure ether pickaxe: the forge's last tool
    when 'forge' then exists (select 1 from uniques where user_id = me and world = w and item = 202)
    -- a validator relit (or placed) under your name
    when 'awakening' then nv >= 1
    -- three validators, both boss trophies, and a kill during a network attack
    when 'network' then nv >= 3
                     and exists (select 1 from uniques where user_id = me and world = w and item = 205)
                     and exists (select 1 from uniques where user_id = me and world = w and item = 206)
                     and exists (select 1 from network_events where world = w and participants ? me::text)
    -- the Merge Aegis: both twins brought down together (030)
    when 'merge' then exists (select 1 from uniques where user_id = me and world = w and item = 209)
    -- an AND, an OR and a NOT gate standing in the world, placed by you
    when 'circuits' then (select count(distinct (id - 112) / 4) from blocks
                          where world = w and placed_by = me::text and id between 112 and 123) = 3
  end;
  if not proof then return _no('chapter not finished'); end if;
  insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, cid);
  perform _gwei(me, w, g);
  return jsonb_build_object('ok', true, 'cosmetic', cid, 'gwei', g, 'total_gwei', _gwei_balance(me, w));
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 031_no_built_validators.sql ════════════════
-- 031: validators are only ever relit, never built. Crafting one (8 crystals, 4 marble) was a shortcut
-- around the whole Awakening (genesis rock, a validator heart, a guarded ruin) that still paid Gwei and
-- counted for the chapters' validator objectives and the leaderboard. The recipe is gone (rules.js), and
-- placing a Validator block (13) is refused here; validators already placed keep working as before.
-- Same _core_place as 020_validators.sql, minus its validator branch.
-- Requires 001_schema.sql, 002_security.sql, 010_bed.sql, 020_validators.sql. Replayable without error.

create or replace function public._core_place(w text, px int, py int, pz int, it int, bid int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); pl players; cur int; cr rule_blocks; rb rule_blocks; below int; up int; ch jsonb := '[]'; inv jsonb := '{}'; s int;
  odx int; odz int; ocur int; ocr rule_blocks;
begin
  pl := _player(me, w);
  if py < 1 or py >= 64 or abs(px) >= 100000 or abs(pz) >= 100000 then return _no('out of the world'); end if;
  if not exists (select 1 from rule_place where item = it and block = bid) then return _no('item not placeable'); end if;
  if bid = 13 then return _no('validators are relit, not built'); end if;
  if _count(me, w, it) < 1 then return _no('empty inventory', jsonb_build_object('inv', jsonb_build_object(it::text, 0))); end if;
  if not _can_build(me, w, px, pz) then return _no('protected'); end if;
  cur := _cell(w, px, py, pz); select * into cr from rule_blocks where id = cur;
  if cur <> 0 and cr.kind not in ('water', 'cross') then return _no('space occupied', jsonb_build_object('cell', cur)); end if;
  select * into rb from rule_blocks where id = bid;
  below := _cell(w, px, py - 1, pz);
  if rb.kind = 'cross' and below not in (1, 2) then return _no('needs support'); end if;
  if rb.kind in ('plate', 'cable', 'lever') and not coalesce((select solid from rule_blocks where id = below), false) then return _no('needs support'); end if;
  if rb.kind = 'door' then
    if py + 1 >= 64 then return _no('out of the world'); end if;
    up := _cell(w, px, py + 1, pz);
    if up <> 0 and (select kind from rule_blocks where id = up) not in ('water', 'cross') then return _no('space occupied'); end if;
  elsif rb.kind like 'bed%f' then
    odx := case rb.kind when 'bed0f' then 0 when 'bed1f' then -1 when 'bed2f' then 0 when 'bed3f' then 1 end;
    odz := case rb.kind when 'bed0f' then -1 when 'bed1f' then 0 when 'bed2f' then 1 when 'bed3f' then 0 end;
    ocur := _cell(w, px + odx, py, pz + odz); select * into ocr from rule_blocks where id = ocur;
    if ocur <> 0 and ocr.kind not in ('water', 'cross') then return _no('space occupied', jsonb_build_object('cell', ocur)); end if;
  end if;
  inv := _give(me, w, it, -1, inv);
  update players set serial = serial + 1 where user_id = me and world = w returning serial into s;
  ch := ch || _set(w, px, py, pz, bid, me, pl.name, s);
  if rb.kind = 'door' then ch := ch || _set(w, px, py + 1, pz, bid + 1, me, pl.name, s);
  elsif rb.kind like 'bed%f' then ch := ch || _set(w, px + odx, py, pz + odz, bid + 4, me, pl.name, s);
  end if;
  return jsonb_build_object('ok', true, 'changes', ch, 'inv', inv, 'serial', s);
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 032_shop.sql ════════════════
-- 032: a shop worth coming back to. Wearables in slots (head, back, companion, trail...), collections,
-- and a weekly offer: each week (Monday 00:00 UTC) three regular wearables are 25% off and one "limited"
-- piece is for sale, the only week it can be bought. The picks are computed here exactly as
-- supabase/functions/_shared/rules.js's shopFeatured() does: change both together. Block packs (a
-- cosmetic that grants items) can now be bought again and again. Still purely decorative.
-- Requires 022_cosmetics.sql (and 029_chapters.sql's not-for-sale rule, kept). Replayable without error.

alter table public.rule_cosmetics add column if not exists limited boolean not null default false;

create or replace function public._shop_week() returns integer
language sql stable as $$
  select floor((extract(epoch from now()) - 345600) / 604800)::int
$$;

-- this week's discounted ids (3) and limited id (or null), same picks as rules.js's shopFeatured()
create or replace function public._shop_featured(wk int) returns jsonb
language plpgsql stable set search_path = public as $$
declare reg smallint[]; lim smallint[]; n int; sale jsonb := '[]';
begin
  select coalesce(array_agg(id order by id), '{}') into reg from rule_cosmetics
    where category not in ('combat', 'event', 'title') and price > 0 and not limited and grant_item is null;
  select coalesce(array_agg(id order by id), '{}') into lim from rule_cosmetics where limited;
  n := coalesce(array_length(reg, 1), 0);
  if n > 0 then
    for k in 0..2 loop sale := sale || to_jsonb(reg[((wk * 3 + k) % n) + 1]); end loop;
  end if;
  return jsonb_build_object('sale', sale,
    'limited', case when coalesce(array_length(lim, 1), 0) > 0 then lim[(wk % array_length(lim, 1)) + 1] end);
end $$;

create or replace function public._core_buy_cosmetic(w text, cid int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); rc rule_cosmetics; inv jsonb := '{}'; f jsonb; cost int;
begin
  perform _player(me, w);
  select * into rc from rule_cosmetics where id = cid;
  if not found then return _no('unknown cosmetic'); end if;
  if rc.category in ('combat', 'event', 'title') or rc.price <= 0 then return _no('not for sale'); end if;
  -- a block pack can be bought again; anything else only once
  if rc.grant_item is null and exists (select 1 from cosmetics_owned where user_id = me and world = w and cosmetic_id = rc.id) then
    return _no('already owned');
  end if;
  f := _shop_featured(_shop_week());
  if rc.limited and (f ->> 'limited') is distinct from rc.id::text then return _no('not in the shop this week'); end if;
  cost := case when (f -> 'sale') @> to_jsonb(rc.id) then (rc.price * 3) / 4 else rc.price end;
  if _gwei_balance(me, w) < cost then return _no('not enough gwei', jsonb_build_object('need', cost)); end if;
  perform _gwei(me, w, -cost);
  insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, rc.id) on conflict do nothing;
  if rc.grant_item is not null then inv := _give(me, w, rc.grant_item, coalesce(rc.grant_qty, 1), inv); end if;
  return jsonb_build_object('ok', true, 'cosmetic', rc.id, 'inv', inv, 'paid', cost, 'gwei', _gwei_balance(me, w));
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 033_consumables.sql ════════════════
-- 033: consumables and the Genesis tier. A consumable (rule_items.consumable) is spent one at a time by
-- act_use_item; its effect (healing, speed, night vision, the mobs' ward) plays client-side like the rest
-- of combat, except the Home Beacon's teleport, which the server must allow: it checks that a bed stands
-- where you're going and records that position, so the next move from there isn't refused. A recipe can
-- also require owning a unique item without spending it (rule_recipes.req_unique: the Genesis gear needs
-- a boss trophy). Requires 001_schema.sql, 002_security.sql. Replayable without error.

alter table public.rule_items add column if not exists consumable boolean not null default false;
alter table public.rule_recipes add column if not exists req_unique smallint;

create or replace function public._core_craft(w text, out_id int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); r rule_recipes; k text; v jsonb; inv jsonb := '{}'; u jsonb;
begin
  perform _player(me, w);
  select * into r from rule_recipes where out_item = out_id;
  if not found then return _no('unknown recipe'); end if;
  if r.req_unique is not null and not exists (select 1 from uniques where user_id = me and world = w and item = r.req_unique) then
    return _no('needs a trophy', jsonb_build_object('item', r.req_unique));
  end if;
  for k, v in select * from jsonb_each(r.need) loop
    if _count(me, w, k::int) < v::int then return _no('missing ingredients', jsonb_build_object('item', k::int)); end if;
  end loop;
  for k, v in select * from jsonb_each(r.need) loop inv := _give(me, w, k::int, -(v::int), inv); end loop;
  if r.uniq then u := _mint(me, w, out_id, null); return jsonb_build_object('ok', true, 'inv', inv, 'unique', u); end if;
  inv := _give(me, w, out_id, r.n, inv);
  return jsonb_build_object('ok', true, 'inv', inv);
end $$;

-- bx/by/bz: the Home Beacon's bed (its foot or head), ignored for the other consumables
create or replace function public._core_use_item(w text, item int, bx int, by int, bz int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); inv jsonb := '{}'; c int;
begin
  perform _player(me, w);
  if not exists (select 1 from rule_items where id = item and consumable) then return _no('not usable'); end if;
  if _count(me, w, item) < 1 then return _no('none left'); end if;
  if item = 307 then
    if bx is null then return _no('no bed to go back to'); end if;
    c := _cell(w, bx, by, bz);
    if c is null or c not between 137 and 144 then return _no('that bed is gone', jsonb_build_object('cell', c)); end if;
    update players set pos_x = bx + 0.5, pos_y = by + 1, pos_z = bz + 0.5, pos_at = clock_timestamp()
      where user_id = me and world = w;
  end if;
  inv := _give(me, w, item, -1, inv);
  return jsonb_build_object('ok', true, 'inv', inv, 'item', item);
end $$;

create or replace function public.act_use_item(w text, item int, bx int default null, by int default null, bz int default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w);
begin
  if not _rate(me, 'use_item', 1, 4) then return _no('too many actions'); end if;
  return _core_use_item(w, item, bx, by, bz);
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 034_signs.sql ════════════════
-- 034: signs. A sign block (rules.js ids 160 to 163) can carry one line of text that every player
-- reads. Only whoever placed the sign writes on it; the text goes through the chat's own filter (_mask,
-- 003_moderation.sql), muted players can't write, 60 characters at most. An empty text clears it. A
-- row whose sign was broken is simply not shown (the client only draws text on a standing sign) and is
-- replaced when someone places a new sign there and writes on it. Furniture needs nothing server-side:
-- its blocks go through the usual place/mine rules. Requires 001_schema.sql, 003_moderation.sql.
-- Replayable without error.

create table if not exists public.signs (
  world       text        not null,
  x           integer     not null,
  y           integer     not null,
  z           integer     not null,
  text        text        not null,
  author      uuid        references auth.users (id) on delete cascade,
  author_name text,
  updated_at  timestamptz not null default now(),
  primary key (world, x, y, z)
);
alter table public.signs enable row level security;
drop policy if exists "read signs" on public.signs;
create policy "read signs" on public.signs for select using (true);

create or replace function public._core_sign(w text, px int, py int, pz int, msg text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); p players; t text; c int;
begin
  p := _player(me, w);
  if p.muted_until > now() then return _no('muted'); end if;
  c := _cell(w, px, py, pz);
  if c is null or c not between 160 and 163 then return _no('not a sign', jsonb_build_object('cell', c)); end if;
  if not exists (select 1 from blocks where world = w and x = px and y = py and z = pz and placed_by = me::text) then
    return _no('not your sign');
  end if;
  t := left(btrim(regexp_replace(regexp_replace(coalesce(msg, ''), '[[:cntrl:]]', ' ', 'g'), '\s+', ' ', 'g')), 60);
  if t = '' then
    delete from signs where world = w and x = px and y = py and z = pz;
    return jsonb_build_object('ok', true, 'text', '');
  end if;
  t := _mask(t);
  insert into signs (world, x, y, z, text, author, author_name) values (w, px, py, pz, t, me, p.name)
    on conflict (world, x, y, z) do update set text = excluded.text, author = excluded.author,
      author_name = excluded.author_name, updated_at = now();
  return jsonb_build_object('ok', true, 'text', t);
end $$;

create or replace function public.act_sign(w text, px int, py int, pz int, msg text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w);
begin
  if octet_length(coalesce(msg, '')) > 1000 then return _no('text too long'); end if;
  if not _rate(me, 'sign', 0.5, 4) then return _no('too many actions'); end if;
  return _core_sign(w, px, py, pz, msg);
end $$;

do $$ begin
  begin alter publication supabase_realtime add table public.signs; exception when duplicate_object then null; when undefined_object then null; end;
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 035_player_count.sql ════════════════
-- 035: how many nicknames a world has. Players can only read their own row (001_schema.sql), so the
-- count goes through this function: it returns a number and nothing else, no name, no id. A player
-- counts once they have a nickname in that world. Requires 001_schema.sql. Replayable without error.

create index if not exists players_world on public.players (world);

create or replace function public.world_player_count(w text) returns integer
language sql stable security definer set search_path = public as $$
  select count(*)::int from players where world = w and coalesce(btrim(name), '') <> '';
$$;

revoke all on function public.world_player_count(text) from public, anon;
grant execute on function public.world_player_count(text) to authenticated;

-- ════════════════ 036_sign_reports.sql ════════════════
-- 036: reporting a sign. Right-click someone else's sign, then "Report": three different players within
-- 24 hours take its text down (the board itself stays), and its author is muted the same way as for the
-- chat (003_moderation.sql: 1 hour, doubling each time, 16 hours at most): no chat, no new sign text.
-- The same safeguards as act_report: only a player who has genuinely played in this world can report,
-- one report per sign and per player, rate limited. Requires 003_moderation.sql, 034_signs.sql.
-- By hand, for the game's owner (SQL Editor): the signs reported lately
--   select s.x, s.y, s.z, s.text, s.author_name, count(r.*) from signs s join sign_reports r using (world, x, y, z)
--     where s.world = 'principal' group by 1, 2, 3, 4, 5 order by 6 desc;
-- and to take one down at once: delete from signs where world = 'principal' and x = … and y = … and z = …;
-- Replayable without error.

create table if not exists public.sign_reports (
  world    text        not null,
  x        integer     not null,
  y        integer     not null,
  z        integer     not null,
  reporter uuid        not null references auth.users (id) on delete cascade,
  at       timestamptz not null default now(),
  primary key (world, x, y, z, reporter)
);
alter table public.sign_reports enable row level security; -- no policy: functions only

create or replace function public._core_report_sign(w text, px int, py int, pz int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); s signs; n int; d interval; author players;
begin
  -- against throwaway accounts made to silence someone: must have genuinely played in this world
  if not exists (select 1 from players where user_id = me and world = w and serial >= 20
                 and created_at < now() - interval '2 hours') then
    return _no('must have played a little');
  end if;
  select * into s from signs where world = w and x = px and y = py and z = pz;
  if s.text is null then return _no('no sign here'); end if;
  if s.author = me then return _no('your own sign'); end if;
  insert into sign_reports (world, x, y, z, reporter) values (w, px, py, pz, me)
    on conflict (world, x, y, z, reporter) do update set at = now();
  select count(*) into n from sign_reports where world = w and x = px and y = py and z = pz and at > now() - interval '24 hours';
  if n < 3 then return jsonb_build_object('ok', true, 'removed', false); end if;
  delete from signs where world = w and x = px and y = py and z = pz;
  delete from sign_reports where world = w and x = px and y = py and z = pz;   -- start over for whatever comes next
  select * into author from players where user_id = s.author and world = w;
  if author.user_id is not null and coalesce(author.muted_until, '-infinity') < now() then
    d := interval '1 hour' * power(2, least(author.mutes, 4));
    update players set muted_until = now() + d, mutes = mutes + 1 where user_id = author.user_id and world = w;
  end if;
  return jsonb_build_object('ok', true, 'removed', true);
end $$;

create or replace function public.act_report_sign(w text, px int, py int, pz int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w);
begin
  if not _rate(me, 'report', 0.1, 5) then return _no('too many actions'); end if;
  return _core_report_sign(w, px, py, pz);
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 037_diamond_shards.sql ════════════════
-- 037: Diamond Shards (#110) within reach from the start. Until now they only came from relighting a
-- validator once 100 were lit in the world (014, 020), so on a fresh world the Radiant Diamond and the
-- Genesis Blade and Plating (4 shards each) were out of reach for weeks. Now also: every boss kill (the
-- Titan and the Plasma Core 1 or 2, the Merge twins 2) and every tower's treasure chest (1). The relight
-- source stays, for the late game. act_loot_mob is 030's with only the boss branches extended.
-- Requires 025_tower_treasure.sql, 030_merge_twins.sql. Replayable without error.

create or replace function public._seed_tower_chest(w text, px int, py int, pz int) returns void
language plpgsql security definer set search_path = public as $$
begin
  if exists (select 1 from chests where world = w and x = px and y = py and z = pz) then return; end if;
  if exists (select 1 from blocks where world = w and x = px and y = py and z = pz) then return; end if;
  insert into chests (world, x, y, z, items) values (w, px, py, pz,
    jsonb_build_object('101', 15 + floor(random() * 11)::int, '103', 4 + floor(random() * 5)::int, '110', 1) -- + a Diamond Shard
      || case when random() < 0.5 then jsonb_build_object('104', 1) else '{}'::jsonb end)
    on conflict do nothing;
end $$;

create or replace function public.act_loot_mob(w text, mob_type text, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); e text; it int; inv jsonb := '{}'; r real; u jsonb; cid smallint; g int; bonus jsonb; aw record; sh int;
begin
  -- 030: the Merge twins, reported once, when both fall together — a guaranteed Merge Aegis, ~20% a bonus
  if mob_type = 'merge_twins' then
    if not _rate(me, 'loot_boss', 0.05, 1) then return _no('too many actions'); end if;
    e := _check_pos(me, w, ex, ey, ez);
    if e is not null then return _no(e); end if;
    u := _mint(me, w, 209, null);
    if random() < 0.2 then bonus := _mint(me, w, 210, null); end if;
    sh := 2;                                                    -- 037: two Diamond Shards, both twins down
    inv := _give(me, w, 110, sh, inv);
    return jsonb_build_object('ok', true, 'inv', inv, 'unique', u, 'bonus', bonus, 'shards', sh);
  end if;
  if mob_type = 'corrupted_node' then
    if not _rate(me, 'attack_node', 0.3, 6) then return _no('too many actions'); end if;
    e := _check_pos(me, w, ex, ey, ez);
    if e is not null then return _no(e); end if;
    if sqrt((ex - 8) ^ 2 + (ez - 8) ^ 2) > 30 then return _no('too far from the Atrium'); end if;
    select * into aw from _attack_window();
    if not aw.active then return _no('no attack right now'); end if;
    insert into network_events (world, window_id, kills, participants) values (w, aw.window_id, 1, jsonb_build_object(me::text, 1))
      on conflict (world, window_id) do update set kills = network_events.kills + 1,
        participants = network_events.participants || jsonb_build_object(me::text, coalesce((network_events.participants ->> me::text)::int, 0) + 1);
    r := random();
    if r < 0.08 then
      select id into cid from rule_cosmetics where category = 'event'
        and id not in (select cosmetic_id from cosmetics_owned where user_id = me and world = w) order by random() limit 1;
      if cid is not null then
        insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, cid);
        return jsonb_build_object('ok', true, 'inv', inv, 'cosmetic', cid);
      end if;
    elsif r < 0.33 then
      g := 10 + floor(random() * 41)::int;
      perform _gwei(me, w, g);
      return jsonb_build_object('ok', true, 'inv', inv, 'gwei', g, 'total_gwei', _gwei_balance(me, w));
    end if;
    inv := _give(me, w, 101, 1 + floor(random() * 2)::int, inv); -- no whiffed kills during the event: a guaranteed small bundle
    return jsonb_build_object('ok', true, 'inv', inv);
  end if;
  if mob_type in ('titan', 'plasma_core') then
    if not _rate(me, 'loot_boss', 0.05, 1) then return _no('too many actions'); end if;
    e := _check_pos(me, w, ex, ey, ez);
    if e is not null then return _no(e); end if;
    u := _mint(me, w, case when mob_type = 'titan' then 205 else 206 end, null);
    if random() < 0.2 then
      bonus := _mint(me, w, case when mob_type = 'titan' then 207 else 208 end, null);
    end if;
    sh := 1 + floor(random() * 2)::int;                         -- 037: one or two Diamond Shards
    inv := _give(me, w, 110, sh, inv);
    return jsonb_build_object('ok', true, 'inv', inv, 'unique', u, 'bonus', bonus, 'shards', sh);
  end if;
  if not _rate(me, 'loot_mob', 0.2, 5) then return _no('too many actions'); end if;
  e := _check_pos(me, w, ex, ey, ez);
  if e is not null then return _no(e); end if;
  -- epic (~3%): a combat-exclusive cosmetic the player doesn't already own; falls through to the
  -- common table once every combat cosmetic is collected. rare (~12%): a small Gwei bonus.
  r := random();
  if r < 0.03 then
    select id into cid from rule_cosmetics where category = 'combat'
      and id not in (select cosmetic_id from cosmetics_owned where user_id = me and world = w)
      order by random() limit 1;
    if cid is not null then
      insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, cid);
      return jsonb_build_object('ok', true, 'inv', inv, 'cosmetic', cid);
    end if;
  elsif r < 0.15 then
    g := 10 + floor(random() * 41)::int; -- 10..50
    perform _gwei(me, w, g);
    return jsonb_build_object('ok', true, 'inv', inv, 'gwei', g, 'total_gwei', _gwei_balance(me, w));
  end if;
  -- common (unchanged): the existing per-mob-type resource chance, its own independent roll
  r := random();
  it := case mob_type
    when 'shadow' then case when r < 0.5 then 101 end
    when 'guardian' then case when r < 0.35 then 101 when r < 0.5 then 103 end
    when 'sentinel' then case when r < 0.4 then 103 end
    when 'wraith' then case when r < 0.25 then 104 when r < 0.65 then 103 end
    when 'warden' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'garden_guardian' then case when r < 0.35 then 101 when r < 0.5 then 103 end
    when 'prowler' then case when r < 0.5 then 101 end
    when 'sky_raider' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'water_lurker' then case when r < 0.25 then 103 when r < 0.5 then 104 end
    when 'bat' then case when r < 0.45 then 101 end
    when 'crawler' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'golem' then case when r < 0.3 then 103 when r < 0.55 then 104 end
    else null
  end;
  if it is null then return jsonb_build_object('ok', true, 'inv', inv); end if;
  inv := _give(me, w, it, 1, inv);
  return jsonb_build_object('ok', true, 'inv', inv, 'item', it);
end $$;


do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 038_block_history.sql ════════════════
-- 038: the block explorer. Every change to a block (placed, mined) is logged with who did it and when,
-- and block_info() gives a block's story to any player who looks at it (I key, 07-interface.js):
-- who placed it, when, how many blocks that builder has standing in the world, and its last changes.
-- The log is filled by a trigger on blocks, so every act_* function that writes a block feeds it
-- without being touched. Opening a door or a lever (_flip: same author, same serial) isn't a change of
-- hands and isn't logged. Only the last 12 changes of each block are kept.
-- Names only, never an account id: the same nicknames everyone already sees over the blocks.
-- Requires 001_schema.sql. Replayable without error.

create table if not exists public.block_history (
  world      text        not null,
  x          integer     not null,
  y          integer     not null,
  z          integer     not null,
  at         timestamptz not null default now(),
  seq        bigserial,
  id         smallint    not null,  -- the block after the change (0: mined)
  prev       smallint,              -- the block before it (null: the generated terrain's, unknown here)
  actor      uuid,                  -- who did it (null: the server itself)
  actor_name text,
  primary key (world, x, y, z, seq)
);
alter table public.block_history enable row level security; -- no policy: read through block_info()

create or replace function public._log_block() returns trigger
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); nm text;
begin
  if tg_op = 'UPDATE' then
    if new.id = old.id then return new; end if;
    -- a door or a lever switching state: the same signature, not a new owner
    if new.id <> 0 and old.id <> 0 and new.placed_by is not distinct from old.placed_by
       and new.serial is not distinct from old.serial then return new; end if;
  end if;
  if me is not null then select name into nm from players where user_id = me and world = new.world; end if;
  insert into block_history (world, x, y, z, id, prev, actor, actor_name)
    values (new.world, new.x, new.y, new.z, new.id, case when tg_op = 'UPDATE' then old.id end, me, nm);
  delete from block_history h where h.world = new.world and h.x = new.x and h.y = new.y and h.z = new.z
    and h.seq <= (select seq from block_history k where k.world = new.world and k.x = new.x and k.y = new.y and k.z = new.z
                  order by seq desc offset 12 limit 1);
  return new;
end $$;

drop trigger if exists blocks_history on public.blocks;
create trigger blocks_history after insert or update on public.blocks
  for each row execute function public._log_block();

-- a block's story: its current signature, the builder's standing block count, its last changes (newest first)
create or replace function public.block_info(w text, px int, py int, pz int) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare b blocks; n int := 0;
begin
  select * into b from blocks where world = w and x = px and y = py and z = pz;
  if b.placed_by is not null then
    select count(*) into n from blocks where world = w and placed_by = b.placed_by and id <> 0;
  end if;
  return jsonb_build_object(
    'id', b.id,
    'name', b.placed_name,
    'serial', b.serial,
    'at', case when b.placed_by is not null then b.updated_at end,
    'builder_blocks', n,
    'history', coalesce((select jsonb_agg(jsonb_build_object('at', h.at, 'id', h.id, 'prev', h.prev, 'name', h.actor_name) order by h.seq desc)
                         from block_history h where h.world = w and h.x = px and h.y = py and h.z = pz), '[]'::jsonb));
end $$;

revoke all on function public.block_info(text, int, int, int) from public, anon;
grant execute on function public.block_info(text, int, int, int) to authenticated;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 039_front_runner.sql ════════════════
-- 039: the Mempool (arenaAt(), world.js), an open-air colosseum ruled by the Front-Runner, a MEV bot boss
-- (src/game/16-mobs.js). The client reports a 'front_runner' kill like the other bosses; it pays the same
-- way: a guaranteed unique (211, the Front-Runner Boots: owned, you move a little faster), an independent
-- ~20% bonus keepsake (212, the Flashbots Bundle) and two Diamond Shards, under the shared loot_boss rate
-- limit. Its minions, the Sandwich Bots ('mev_bot'), drop like ordinary mobs. act_loot_mob is 037's with
-- only these two additions. Requires 037_diamond_shards.sql. Replayable without error.

create or replace function public.act_loot_mob(w text, mob_type text, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); e text; it int; inv jsonb := '{}'; r real; u jsonb; cid smallint; g int; bonus jsonb; aw record; sh int;
begin
  -- 030: the Merge twins, reported once, when both fall together — a guaranteed Merge Aegis, ~20% a bonus
  if mob_type = 'merge_twins' then
    if not _rate(me, 'loot_boss', 0.05, 1) then return _no('too many actions'); end if;
    e := _check_pos(me, w, ex, ey, ez);
    if e is not null then return _no(e); end if;
    u := _mint(me, w, 209, null);
    if random() < 0.2 then bonus := _mint(me, w, 210, null); end if;
    sh := 2;                                                    -- 037: two Diamond Shards, both twins down
    inv := _give(me, w, 110, sh, inv);
    return jsonb_build_object('ok', true, 'inv', inv, 'unique', u, 'bonus', bonus, 'shards', sh);
  end if;
  -- 039: the Front-Runner, the Mempool's boss: guaranteed Front-Runner Boots, ~20% a Flashbots Bundle,
  -- two Diamond Shards; the same loot_boss rate limit as every other boss
  if mob_type = 'front_runner' then
    if not _rate(me, 'loot_boss', 0.05, 1) then return _no('too many actions'); end if;
    e := _check_pos(me, w, ex, ey, ez);
    if e is not null then return _no(e); end if;
    u := _mint(me, w, 211, null);
    if random() < 0.2 then bonus := _mint(me, w, 212, null); end if;
    sh := 2;
    inv := _give(me, w, 110, sh, inv);
    return jsonb_build_object('ok', true, 'inv', inv, 'unique', u, 'bonus', bonus, 'shards', sh);
  end if;
  if mob_type = 'corrupted_node' then
    if not _rate(me, 'attack_node', 0.3, 6) then return _no('too many actions'); end if;
    e := _check_pos(me, w, ex, ey, ez);
    if e is not null then return _no(e); end if;
    if sqrt((ex - 8) ^ 2 + (ez - 8) ^ 2) > 30 then return _no('too far from the Atrium'); end if;
    select * into aw from _attack_window();
    if not aw.active then return _no('no attack right now'); end if;
    insert into network_events (world, window_id, kills, participants) values (w, aw.window_id, 1, jsonb_build_object(me::text, 1))
      on conflict (world, window_id) do update set kills = network_events.kills + 1,
        participants = network_events.participants || jsonb_build_object(me::text, coalesce((network_events.participants ->> me::text)::int, 0) + 1);
    r := random();
    if r < 0.08 then
      select id into cid from rule_cosmetics where category = 'event'
        and id not in (select cosmetic_id from cosmetics_owned where user_id = me and world = w) order by random() limit 1;
      if cid is not null then
        insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, cid);
        return jsonb_build_object('ok', true, 'inv', inv, 'cosmetic', cid);
      end if;
    elsif r < 0.33 then
      g := 10 + floor(random() * 41)::int;
      perform _gwei(me, w, g);
      return jsonb_build_object('ok', true, 'inv', inv, 'gwei', g, 'total_gwei', _gwei_balance(me, w));
    end if;
    inv := _give(me, w, 101, 1 + floor(random() * 2)::int, inv); -- no whiffed kills during the event: a guaranteed small bundle
    return jsonb_build_object('ok', true, 'inv', inv);
  end if;
  if mob_type in ('titan', 'plasma_core') then
    if not _rate(me, 'loot_boss', 0.05, 1) then return _no('too many actions'); end if;
    e := _check_pos(me, w, ex, ey, ez);
    if e is not null then return _no(e); end if;
    u := _mint(me, w, case when mob_type = 'titan' then 205 else 206 end, null);
    if random() < 0.2 then
      bonus := _mint(me, w, case when mob_type = 'titan' then 207 else 208 end, null);
    end if;
    sh := 1 + floor(random() * 2)::int;                         -- 037: one or two Diamond Shards
    inv := _give(me, w, 110, sh, inv);
    return jsonb_build_object('ok', true, 'inv', inv, 'unique', u, 'bonus', bonus, 'shards', sh);
  end if;
  if not _rate(me, 'loot_mob', 0.2, 5) then return _no('too many actions'); end if;
  e := _check_pos(me, w, ex, ey, ez);
  if e is not null then return _no(e); end if;
  -- epic (~3%): a combat-exclusive cosmetic the player doesn't already own; falls through to the
  -- common table once every combat cosmetic is collected. rare (~12%): a small Gwei bonus.
  r := random();
  if r < 0.03 then
    select id into cid from rule_cosmetics where category = 'combat'
      and id not in (select cosmetic_id from cosmetics_owned where user_id = me and world = w)
      order by random() limit 1;
    if cid is not null then
      insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, cid);
      return jsonb_build_object('ok', true, 'inv', inv, 'cosmetic', cid);
    end if;
  elsif r < 0.15 then
    g := 10 + floor(random() * 41)::int; -- 10..50
    perform _gwei(me, w, g);
    return jsonb_build_object('ok', true, 'inv', inv, 'gwei', g, 'total_gwei', _gwei_balance(me, w));
  end if;
  -- common (unchanged): the existing per-mob-type resource chance, its own independent roll
  r := random();
  it := case mob_type
    when 'shadow' then case when r < 0.5 then 101 end
    when 'guardian' then case when r < 0.35 then 101 when r < 0.5 then 103 end
    when 'sentinel' then case when r < 0.4 then 103 end
    when 'wraith' then case when r < 0.25 then 104 when r < 0.65 then 103 end
    when 'warden' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'garden_guardian' then case when r < 0.35 then 101 when r < 0.5 then 103 end
    when 'prowler' then case when r < 0.5 then 101 end
    when 'sky_raider' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'water_lurker' then case when r < 0.25 then 103 when r < 0.5 then 104 end
    when 'bat' then case when r < 0.45 then 101 end
    when 'crawler' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'golem' then case when r < 0.3 then 103 when r < 0.55 then 104 end
    when 'mev_bot' then case when r < 0.5 then 101 end                -- 039: the Front-Runner's Sandwich Bots
    else null
  end;
  if it is null then return jsonb_build_object('ok', true, 'inv', inv); end if;
