-- ════════════════ 040_hovercraft.sql ════════════════
-- 040: hovercraft, the Diamond Gliders (items 213-220, rules.js; src/game/20-hover.js). They are crafted
-- like the special pickaxes (_core_craft mints the unique, nothing new there); what changes is movement:
-- a rider goes twice as fast as a runner, which _check_pos (002_security.sql) would refuse as an
-- impossible move. _check_pos is 002's with one change: the horizontal allowance is twice as large for a
-- player who owns a glider, or who sits close to one who does and moved within the last 20 seconds (the
-- Twin Diamond's back seat: its passenger goes where the driver goes). A rider pings its position every
-- 3 seconds instead of 15, so that driver's position stays fresh.
-- Requires 002_security.sql. Replayable without error.

create or replace function public._check_pos(me uuid, w text, ex real, ey real, ez real, tx int default null, ty int default null, tz int default null)
returns text language plpgsql security definer set search_path = public as $$
declare p players; dt real; horiz real; up real; ok boolean := false; pace real := 9;
begin
  if ex is null or ey is null or ez is null then return 'missing position'; end if;
  if abs(ex) > 100000 or abs(ez) > 100000 or ey < -20 or ey > 80 then return 'position out of the world'; end if;
  select * into p from players where user_id = me and world = w;
  if p.pos_at is null then ok := true;                                   -- first known position
  else
    dt := greatest(extract(epoch from clock_timestamp() - p.pos_at), 0);
    horiz := sqrt((ex - p.pos_x) ^ 2 + (ez - p.pos_z) ^ 2);
    up := ey - p.pos_y;                                                  -- falls aren't limited
    -- 040: on a hovercraft (13.2 blocks/s), or in the back seat of a recently-moved rider's Twin Diamond
    if horiz > 9 * dt + 8 and (
         exists (select 1 from uniques where user_id = me and world = w and item between 213 and 220)
         or exists (select 1 from players o join uniques u on u.user_id = o.user_id and u.world = o.world and u.item between 213 and 216
                    where o.world = w and o.user_id <> me and o.pos_at > clock_timestamp() - interval '20 seconds'
                      and sqrt((ex - o.pos_x) ^ 2 + (ez - o.pos_z) ^ 2) <= 45)) then
      pace := 18;
    end if;
    ok := horiz <= pace * dt + 8 and up <= 9 * dt + 6;                    -- 6.6 blocks/s running pace, with slack for network lag
    if not ok then ok := sqrt((ex - 8.5) ^ 2 + (ez - 10.5) ^ 2) <= 8; end if; -- return to the sanctuary (/sanctuary, falling into the void)
    if not ok then                                                        -- /join: next to a recently-active player
      ok := exists (select 1 from players o where o.world = w and o.user_id <> me and o.pos_at > clock_timestamp() - interval '2 minutes'
                    and sqrt((ex - o.pos_x) ^ 2 + (ez - o.pos_z) ^ 2) <= 6);
    end if;
  end if;
  if not ok then return 'impossible move'; end if;
  if tx is not null and sqrt((tx + 0.5 - ex) ^ 2 + (ty + 0.5 - (ey + 1.6)) ^ 2 + (tz + 0.5 - ez) ^ 2) > 6.5 then
    return 'too far';
  end if;
  update players set pos_x = ex, pos_y = ey, pos_z = ez, pos_at = clock_timestamp() where user_id = me and world = w;
  return null;
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 041_game_server.sql ════════════════
-- 041: the game server (server/, on Fly.io) pays the mobs' loot itself. It runs the mobs and keeps their
-- health, so it knows who really struck a mob before it fell: for each of them it calls srv_loot_mob with
-- the service key (a Fly secret, never in the repository), and the browser no longer asks. While the game
-- server is up for a world (srv_heartbeat, every minute), act_loot_mob refuses: nobody can claim loot for a
-- kill that didn't happen. Without it (down, or no key), act_loot_mob pays as before. It also takes the
-- Ether Tonic (srv_use_item): your hearts live on the game server now, so it heals you only for a tonic
-- it took from your inventory itself. The srv_* functions can only be called with the service key.
-- act_loot_mob's rules are 039's, unchanged (moved into _loot_mob). Requires 039_front_runner.sql, 033_consumables.sql.
-- Replayable without error.

create table if not exists public.game_servers (
  world text primary key,
  seen timestamptz not null default now()
);
alter table public.game_servers enable row level security; -- no policy: only these functions read or write it

-- is the game server running this world right now?
create or replace function public._game_server_on(w text) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from game_servers where world = w and seen > now() - interval '90 seconds')
$$;

-- the loot of a kill, for one player (check_pos: their reported position must match the one on record)
create or replace function public._loot_mob(me uuid, w text, mob_type text, ex real, ey real, ez real, check_pos boolean) returns jsonb
language plpgsql security definer set search_path = public as $$
declare e text; it int; inv jsonb := '{}'; r real; u jsonb; cid smallint; g int; bonus jsonb; aw record; sh int;
begin
  -- 030: the Merge twins, reported once, when both fall together — a guaranteed Merge Aegis, ~20% a bonus
  if mob_type = 'merge_twins' then
    if not _rate(me, 'loot_boss', 0.05, 1) then return _no('too many actions'); end if;
    if check_pos then e := _check_pos(me, w, ex, ey, ez); end if;
    if e is not null then return _no(e); end if;
    u := _mint(me, w, 209, null);
    if random() < 0.2 then bonus := _mint(me, w, 210, null); end if;
    sh := 2;                                                    -- 037: two Diamond Shards, both twins down
    inv := _give(me, w, 110, sh, inv);
    return jsonb_build_object('ok', true, 'inv', inv, 'unique', u, 'bonus', bonus, 'shards', sh);
  end if;
  -- 039: the Front-Runner, the Mempool's boss: guaranteed Front-Runner Boots, ~20% a Flashbots Bundle,
  -- two Diamond Shards; the same loot_boss rate limit as every other boss
  if mob_type = 'front_runner' then
    if not _rate(me, 'loot_boss', 0.05, 1) then return _no('too many actions'); end if;
    if check_pos then e := _check_pos(me, w, ex, ey, ez); end if;
    if e is not null then return _no(e); end if;
    u := _mint(me, w, 211, null);
    if random() < 0.2 then bonus := _mint(me, w, 212, null); end if;
    sh := 2;
    inv := _give(me, w, 110, sh, inv);
    return jsonb_build_object('ok', true, 'inv', inv, 'unique', u, 'bonus', bonus, 'shards', sh);
  end if;
  if mob_type = 'corrupted_node' then
    if not _rate(me, 'attack_node', 0.3, 6) then return _no('too many actions'); end if;
    if check_pos then e := _check_pos(me, w, ex, ey, ez); end if;
    if e is not null then return _no(e); end if;
    if sqrt((ex - 8) ^ 2 + (ez - 8) ^ 2) > 30 then return _no('too far from the Atrium'); end if;
    select * into aw from _attack_window();
    if not aw.active then return _no('no attack right now'); end if;
    insert into network_events (world, window_id, kills, participants) values (w, aw.window_id, 1, jsonb_build_object(me::text, 1))
      on conflict (world, window_id) do update set kills = network_events.kills + 1,
        participants = network_events.participants || jsonb_build_object(me::text, coalesce((network_events.participants ->> me::text)::int, 0) + 1);
    r := random();
    if r < 0.08 then
      select id into cid from rule_cosmetics where category = 'event'
        and id not in (select cosmetic_id from cosmetics_owned where user_id = me and world = w) order by random() limit 1;
      if cid is not null then
        insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, cid);
        return jsonb_build_object('ok', true, 'inv', inv, 'cosmetic', cid);
      end if;
    elsif r < 0.33 then
      g := 10 + floor(random() * 41)::int;
      perform _gwei(me, w, g);
      return jsonb_build_object('ok', true, 'inv', inv, 'gwei', g, 'total_gwei', _gwei_balance(me, w));
    end if;
    inv := _give(me, w, 101, 1 + floor(random() * 2)::int, inv); -- no whiffed kills during the event: a guaranteed small bundle
    return jsonb_build_object('ok', true, 'inv', inv);
  end if;
  if mob_type in ('titan', 'plasma_core') then
    if not _rate(me, 'loot_boss', 0.05, 1) then return _no('too many actions'); end if;
    if check_pos then e := _check_pos(me, w, ex, ey, ez); end if;
    if e is not null then return _no(e); end if;
    u := _mint(me, w, case when mob_type = 'titan' then 205 else 206 end, null);
    if random() < 0.2 then
      bonus := _mint(me, w, case when mob_type = 'titan' then 207 else 208 end, null);
    end if;
    sh := 1 + floor(random() * 2)::int;                         -- 037: one or two Diamond Shards
    inv := _give(me, w, 110, sh, inv);
    return jsonb_build_object('ok', true, 'inv', inv, 'unique', u, 'bonus', bonus, 'shards', sh);
  end if;
  if not _rate(me, 'loot_mob', 0.2, 5) then return _no('too many actions'); end if;
  if check_pos then e := _check_pos(me, w, ex, ey, ez); end if;
  if e is not null then return _no(e); end if;
  -- epic (~3%): a combat-exclusive cosmetic the player doesn't already own; falls through to the
  -- common table once every combat cosmetic is collected. rare (~12%): a small Gwei bonus.
  r := random();
  if r < 0.03 then
    select id into cid from rule_cosmetics where category = 'combat'
      and id not in (select cosmetic_id from cosmetics_owned where user_id = me and world = w)
      order by random() limit 1;
    if cid is not null then
      insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, cid);
      return jsonb_build_object('ok', true, 'inv', inv, 'cosmetic', cid);
    end if;
  elsif r < 0.15 then
    g := 10 + floor(random() * 41)::int; -- 10..50
    perform _gwei(me, w, g);
    return jsonb_build_object('ok', true, 'inv', inv, 'gwei', g, 'total_gwei', _gwei_balance(me, w));
  end if;
  -- common (unchanged): the existing per-mob-type resource chance, its own independent roll
  r := random();
  it := case mob_type
    when 'shadow' then case when r < 0.5 then 101 end
    when 'guardian' then case when r < 0.35 then 101 when r < 0.5 then 103 end
    when 'sentinel' then case when r < 0.4 then 103 end
    when 'wraith' then case when r < 0.25 then 104 when r < 0.65 then 103 end
    when 'warden' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'garden_guardian' then case when r < 0.35 then 101 when r < 0.5 then 103 end
    when 'prowler' then case when r < 0.5 then 101 end
    when 'sky_raider' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'water_lurker' then case when r < 0.25 then 103 when r < 0.5 then 104 end
    when 'bat' then case when r < 0.45 then 101 end
    when 'crawler' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'golem' then case when r < 0.3 then 103 when r < 0.55 then 104 end
    when 'mev_bot' then case when r < 0.5 then 101 end                -- 039: the Front-Runner's Sandwich Bots
    else null
  end;
  if it is null then return jsonb_build_object('ok', true, 'inv', inv); end if;
  inv := _give(me, w, it, 1, inv);
  return jsonb_build_object('ok', true, 'inv', inv, 'item', it);
end $$;

create or replace function public.act_loot_mob(w text, mob_type text, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w);
begin
  if _game_server_on(w) then return _no('the game server pays the loot'); end if;
  return _loot_mob(me, w, mob_type, ex, ey, ez, true);
end $$;

-- the game server: this player took part in that kill (it checked every blow), at (ex, ey, ez)
create or replace function public.srv_loot_mob(p_user uuid, w text, mob_type text, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from players where user_id = p_user and world = w) then return _no('unknown player'); end if;
  return _loot_mob(p_user, w, mob_type, ex, ey, ez, false);
end $$;

-- the game server: an Ether Tonic (303) drunk, taken from the inventory before it heals
create or replace function public.srv_use_item(p_user uuid, w text, item int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare inv jsonb := '{}';
begin
  if item <> 303 then return _no('not usable here'); end if;
  if not exists (select 1 from players where user_id = p_user and world = w) then return _no('unknown player'); end if;
  if not _rate(p_user, 'use_item', 1, 4) then return _no('too many actions'); end if;
  if _count(p_user, w, item) < 1 then return _no('none left'); end if;
  inv := _give(p_user, w, item, -1, inv);
  return jsonb_build_object('ok', true, 'inv', inv, 'item', item);
end $$;

-- the game server is up for these worlds (called every minute)
create or replace function public.srv_heartbeat(worlds text[]) returns void
language sql security definer set search_path = public as $$
  insert into game_servers (world, seen) select distinct x, now() from unnest(worlds) as x where char_length(x) between 1 and 32
    on conflict (world) do update set seen = now();
$$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;
-- the game server's own functions: the service key only
revoke all on function public.srv_loot_mob(uuid, text, text, real, real, real) from public, anon, authenticated;
revoke all on function public.srv_use_item(uuid, text, int) from public, anon, authenticated;
revoke all on function public.srv_heartbeat(text[]) from public, anon, authenticated;
grant execute on function public.srv_loot_mob(uuid, text, text, real, real, real) to service_role;
grant execute on function public.srv_use_item(uuid, text, int) to service_role;
grant execute on function public.srv_heartbeat(text[]) to service_role;

-- ════════════════ 042_world_restore.sql ════════════════
-- 042: putting a world back the way it was generated, except where it's claimed. Every change a player
-- makes to the terrain is a row in `blocks`, laid over the frozen terrain (`chunks`): erasing those rows
-- brings the original back (holes filled, trees grown back, wild builds gone). Run by hand, in the SQL
-- Editor, by the game's owner only (no player, not even the game server, can call it):
--   select admin_restore_world('principal');          -- a preview: what would go, what stays, where
--   select admin_restore_world('principal', true);    -- the real thing
-- What stays: every block inside a claimed chunk, chests (and what's in them, tower treasures included),
-- signs, and every validator with the ruin around it (relit columns and capstone). The screens in that
-- world are told (`world_restores`, read in real time) and reload; the game server reads its terrain again.
-- A tower chest that was broken comes back empty: _seed_tower_chest no longer seeds a cell that has a
-- history (block_history), so a restore never refills a treasure someone already took.
-- Requires 004_chests.sql, 020_validators.sql, 034_signs.sql, 037_diamond_shards.sql, 038_block_history.sql.
-- Replayable without error.

create table if not exists public.world_restores (
  world  text        primary key,
  at     timestamptz not null default now(),
  erased integer     not null default 0
);
alter table public.world_restores enable row level security;
drop policy if exists "read world restores" on public.world_restores;
create policy "read world restores" on public.world_restores for select using (true);
do $$ begin
  begin alter publication supabase_realtime add table public.world_restores; exception when duplicate_object then null; when undefined_object then null; end;
end $$;

-- 037's seeding, plus: a cell that ever changed (mined, built on) is no pristine tower chest
create or replace function public._seed_tower_chest(w text, px int, py int, pz int) returns void
language plpgsql security definer set search_path = public as $$
begin
  if exists (select 1 from chests where world = w and x = px and y = py and z = pz) then return; end if;
  if exists (select 1 from blocks where world = w and x = px and y = py and z = pz) then return; end if;
  if exists (select 1 from block_history where world = w and x = px and y = py and z = pz) then return; end if;
  insert into chests (world, x, y, z, items) values (w, px, py, pz,
    jsonb_build_object('101', 15 + floor(random() * 11)::int, '103', 4 + floor(random() * 5)::int, '110', 1) -- + a Diamond Shard
      || case when random() < 0.5 then jsonb_build_object('104', 1) else '{}'::jsonb end)
    on conflict do nothing;
end $$;

-- the blocks a restore would erase: outside every claim, not a chest, not a sign, not by a validator
create or replace function public._restore_victims(w text)
returns table (x int, y int, z int, id smallint, placed_name text)
language sql stable security definer set search_path = public as $$
  select b.x, b.y, b.z, b.id, b.placed_name from blocks b
  where b.world = w
    and not exists (select 1 from claims c where c.world = w and c.cx = b.x >> 4 and c.cz = b.z >> 4)
    and not exists (select 1 from chests k where k.world = w and k.x = b.x and k.y = b.y and k.z = b.z)
    and not exists (select 1 from signs s where s.world = w and s.x = b.x and s.y = b.y and s.z = b.z)
    -- a validator's ruin: its columns 2 blocks out on each side, a capstone above
    and not exists (select 1 from validators v where v.world = w
                    and abs(b.x - v.x) <= 3 and abs(b.z - v.z) <= 3 and b.y between v.y - 2 and v.y + 6);
$$;

create or replace function public.admin_restore_world(w text, apply boolean default false) returns jsonb
language plpgsql security definer set search_path = public as $$
declare n int; total int; claimed int; zones jsonb;
begin
  perform set_config('client_min_messages', 'warning', true);
  drop table if exists pg_temp.restore_victims;
  create temp table restore_victims on commit drop as select * from _restore_victims(w);
  select count(*) into n from restore_victims;
  select count(*) into total from blocks b where b.world = w;
  select count(*) into claimed from blocks b where b.world = w
    and exists (select 1 from claims c where c.world = w and c.cx = b.x >> 4 and c.cz = b.z >> 4);
  -- where most of it is: the 10 busiest chunks (their middle), how much was dug, who built there
  select coalesce(jsonb_agg(t.z order by (t.z ->> 'blocks')::int desc), '[]'::jsonb) into zones from (
    select jsonb_build_object('x', (v.x >> 4) * 16 + 8, 'z', (v.z >> 4) * 16 + 8, 'blocks', count(*),
             'mined', count(*) filter (where v.id = 0),
             'builders', coalesce(jsonb_agg(distinct v.placed_name) filter (where v.placed_name is not null), '[]'::jsonb)) as z
    from restore_victims v group by v.x >> 4, v.z >> 4 order by count(*) desc limit 10) t;
  if apply then
    delete from blocks b using restore_victims v where b.world = w and b.x = v.x and b.y = v.y and b.z = v.z;
    get diagnostics n = row_count;
    insert into world_restores (world, at, erased) values (w, now(), n)
      on conflict (world) do update set at = now(), erased = excluded.erased;
  end if;
  return jsonb_build_object(
    'world', w,
    case when apply then 'erased' else 'would_erase' end, n,
    'kept_in_claims', claimed,
    'kept_elsewhere', total - claimed - n, -- chests, signs, validators' ruins
    'zones', zones,
    'next', case when apply then 'the players in this world reload on their own' else format('select admin_restore_world(%L, true);', w) end);
end $$;

revoke all on function public._restore_victims(text) from public, anon, authenticated;
revoke all on function public.admin_restore_world(text, boolean) from public, anon, authenticated, service_role;

-- ════════════════ 043_weekly_attest.sql ════════════════
-- 043: a validator needs attesting once a week, not once a day: players who can only play on weekends
-- keep theirs healthy. _tick_validator is 021's, with the health check's window at 7 days instead of 24h
-- (production, the 24h catch-up cap per tick, and the 3 / 8 missed cycles before damaged / corrupted are
-- unchanged). Requires 021_gwei_cycle_and_maintenance.sql. Replayable without error.

create or replace function public._tick_validator(w text, vid bigint) returns validators
language plpgsql security definer set search_path = public as $$
declare v validators; cycles int; maintained boolean; net int;
begin
  select * into v from validators where id = vid and world = w for update;
  if not found or v.state = 'dormant' or v.owner is null or v.last_cycle_at is null then return v; end if;
  cycles := floor(least(extract(epoch from now() - v.last_cycle_at), 86400) / 300)::int; -- 24h catch-up cap, 300s = 1 cycle
  if cycles <= 0 then return v; end if;
  -- production is always paid for elapsed cycles, whether or not the player checked in: the validator
  -- itself doesn't stop working. Only the health check (missed_cycles / degradation) below is gated on
  -- having actually attested in the last week (043).
  net := greatest(v.gwei_per_cycle - v.maintenance_cost, 0) * cycles;
  if net > 0 then perform _gwei(v.owner, w, net); end if;
  -- maintained = attested within the last 7 days, counting back from now (not from last_cycle_at, which
  -- would let one attestation count as "maintained" forever if nobody ever ticks again)
  maintained := v.last_attested_at is not null and v.last_attested_at >= now() - interval '7 days';
  if maintained then
    update validators set last_cycle_at = last_cycle_at + make_interval(secs => cycles * 300), missed_cycles = 0
      where id = vid returning * into v;
  else
    update validators set last_cycle_at = last_cycle_at + make_interval(secs => cycles * 300),
      missed_cycles = missed_cycles + cycles,
      state = case when missed_cycles + cycles >= 8 then 'corrupted' when missed_cycles + cycles >= 3 then 'damaged' else state end
      where id = vid returning * into v;
  end if;
  return v;
end $$;

-- ════════════════ 044_corrupted_after_8_days.sql ════════════════
-- 044: one step only. A validator not attested for 8 days is corrupted (a Validator Heart repairs it);
-- there's no "damaged" state any more. _tick_validator is 043's with the window at 8 days and no damaged
-- step; validators left damaged by the old rule are active again if attested within the 8 days, and
-- corrupted otherwise (on their next tick). Production is unchanged. Requires 043_weekly_attest.sql.
-- Replayable without error.

create or replace function public._tick_validator(w text, vid bigint) returns validators
language plpgsql security definer set search_path = public as $$
declare v validators; cycles int; maintained boolean; net int;
begin
  select * into v from validators where id = vid and world = w for update;
  if not found or v.state = 'dormant' or v.owner is null or v.last_cycle_at is null then return v; end if;
  cycles := floor(least(extract(epoch from now() - v.last_cycle_at), 86400) / 300)::int; -- 24h catch-up cap, 300s = 1 cycle
  if cycles <= 0 then return v; end if;
  -- production is always paid for elapsed cycles, whether or not the player checked in: the validator
  -- itself doesn't stop working. Only the health check (missed_cycles / degradation) below is gated on
  -- having actually attested in the last 8 days (044).
  net := greatest(v.gwei_per_cycle - v.maintenance_cost, 0) * cycles;
  if net > 0 then perform _gwei(v.owner, w, net); end if;
  -- maintained = attested within the last 8 days, counting back from now (not from last_cycle_at, which
  -- would let one attestation count as "maintained" forever if nobody ever ticks again)
  maintained := v.last_attested_at is not null and v.last_attested_at >= now() - interval '8 days';
  if maintained then
    -- (a validator left damaged by the old rule is healthy again)
    update validators set last_cycle_at = last_cycle_at + make_interval(secs => cycles * 300), missed_cycles = 0,
      state = case when state = 'damaged' then 'active' else state end
      where id = vid returning * into v;
  else
    update validators set last_cycle_at = last_cycle_at + make_interval(secs => cycles * 300),
      missed_cycles = missed_cycles + cycles,
      state = 'corrupted' -- no damaged step any more (044): 8 days without an attestation and it's corrupted
      where id = vid returning * into v;
  end if;
  return v;
end $$;

update validators set state = 'active', missed_cycles = 0
  where state = 'damaged' and last_attested_at >= now() - interval '8 days';

-- ════════════════ 045_restore_regen.sql ════════════════
-- 045: a restore can also regenerate the terrain (GEN 27: the towers and the Merge Sanctum grew). Frozen
-- chunks never change on their own; with regen, the frozen chunks outside the claims are dropped too, and
-- frozen again from the generator deployed now (the freeze function) the next time someone comes by.
-- Deploy the freeze function with the new generator first. Same as 042's admin_restore_world otherwise.
--   select admin_restore_world('principal', false, true);   -- a preview, chunks to regenerate included
--   select admin_restore_world('principal', true, true);    -- the real thing
-- Requires 042_world_restore.sql. Replayable without error.

drop function if exists public.admin_restore_world(text, boolean);
create or replace function public.admin_restore_world(w text, apply boolean default false, regen boolean default false) returns jsonb
language plpgsql security definer set search_path = public as $$
declare n int; total int; claimed int; zones jsonb; chunks_n int := 0;
begin
  perform set_config('client_min_messages', 'warning', true);
  drop table if exists pg_temp.restore_victims;
  create temp table restore_victims on commit drop as select * from _restore_victims(w);
  select count(*) into n from restore_victims;
  select count(*) into total from blocks b where b.world = w;
  select count(*) into claimed from blocks b where b.world = w
    and exists (select 1 from claims c where c.world = w and c.cx = b.x >> 4 and c.cz = b.z >> 4);
  -- where most of it is: the 10 busiest chunks (their middle), how much was dug, who built there
  select coalesce(jsonb_agg(t.z order by (t.z ->> 'blocks')::int desc), '[]'::jsonb) into zones from (
    select jsonb_build_object('x', (v.x >> 4) * 16 + 8, 'z', (v.z >> 4) * 16 + 8, 'blocks', count(*),
             'mined', count(*) filter (where v.id = 0),
             'builders', coalesce(jsonb_agg(distinct v.placed_name) filter (where v.placed_name is not null), '[]'::jsonb)) as z
    from restore_victims v group by v.x >> 4, v.z >> 4 order by count(*) desc limit 10) t;
  -- regen: the frozen terrain outside the claims goes too, and is frozen again from the generator deployed
  -- now (the freeze function), the next time someone comes by: new buildings appear where people played
  if regen then
    select count(*) into chunks_n from chunks c where c.world = w
      and not exists (select 1 from claims cl where cl.world = w and cl.cx = c.cx and cl.cz = c.cz);
  end if;
  if apply then
    delete from blocks b using restore_victims v where b.world = w and b.x = v.x and b.y = v.y and b.z = v.z;
    get diagnostics n = row_count;
    if regen then
      delete from chunks c where c.world = w
        and not exists (select 1 from claims cl where cl.world = w and cl.cx = c.cx and cl.cz = c.cz);
      get diagnostics chunks_n = row_count;
    end if;
    insert into world_restores (world, at, erased) values (w, now(), n)
      on conflict (world) do update set at = now(), erased = excluded.erased;
  end if;
  return jsonb_build_object(
    'world', w,
    case when apply then 'erased' else 'would_erase' end, n,
    'kept_in_claims', claimed,
    'kept_elsewhere', total - claimed - n, -- chests, signs, validators' ruins
    'zones', zones,
    case when apply then 'terrain_regenerated' else 'terrain_to_regenerate' end, case when regen then chunks_n end, -- chunks
    'next', case when apply then 'the players in this world reload on their own'
      else format('select admin_restore_world(%L, true%s);', w, case when regen then ', true' else '' end) end);
end $$;

revoke all on function public.admin_restore_world(text, boolean, boolean) from public, anon, authenticated, service_role;

-- ════════════════ 046_logins.sql ════════════════
-- 046: a login and a password, to find your game on any device. Playing still starts without any
-- account (a guest session kept by the browser, as before); a player can then secure their game with a
-- login of their choosing and a password: no email, nothing personal. On another device, logging in moves
-- the game over to that device's session, the same way a recovery code does (the recovery codes stay).
-- Logins are case-insensitive: "Pierre", "pierre" and "PIERRE" are one login (login_key, lower case),
-- shown as the player typed it. Passwords are kept as bcrypt hashes (pgcrypto); five wrong passwords in a
-- row lock that login for ten minutes, whoever tries.
-- A device whose game left for another one (moved_accounts) is told so, and asked to log in again.
-- For the game's owner, by hand in the SQL Editor (no player, not even the game server, can call them):
--   select admin_login_info('pierre');                       -- whose login, which worlds, a few things they own
--   select admin_reset_password('pierre', 'new-password');   -- a player who forgot it (check it's them first)
-- Requires 001_schema.sql (pgcrypto, recovery), 008_trades.sql, 020_validators.sql, 022_cosmetics.sql,
-- 034_signs.sql, 038_block_history.sql. Replayable without error.

create table if not exists public.logins (
  login_key    text        primary key,           -- the login in lower case: logins are case-insensitive
  login        text        not null,              -- as the player typed it
  user_id      uuid        not null unique references auth.users (id) on delete cascade,
  pass_hash    text        not null,
  fails        integer     not null default 0,     -- wrong passwords in a row
  locked_until timestamptz,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
alter table public.logins enable row level security; -- no policy: only the functions below read or write it

-- a guest session whose game was moved to another device (a login, a recovery code)
create table if not exists public.moved_accounts (
  old_id uuid        primary key,
  login  text,
  at     timestamptz not null default now()
);
alter table public.moved_accounts enable row level security;

-- everything an account owns, handed to another one (old -> me): 022's recovery, plus the trade offers,
-- the signs, the block history, the login. In a world where both have a game, old's game wins (the
-- device's own game there is the one left behind).
create or replace function public._move_account(old uuid, me uuid) returns integer
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  if old is null or me is null or old = me then return 0; end if;
  delete from public.inventory i where i.user_id = me and exists (select 1 from public.players o where o.user_id = old and o.world = i.world);
  delete from public.uniques u where u.user_id = me and exists (select 1 from public.players o where o.user_id = old and o.world = u.world);
  delete from public.cosmetics_owned c where c.user_id = me and exists (select 1 from public.players o where o.user_id = old and o.world = c.world);
  delete from public.players p where p.user_id = me and exists (select 1 from public.players o where o.user_id = old and o.world = p.world);
  update public.players set user_id = me where user_id = old;
  get diagnostics n = row_count;
  update public.inventory set user_id = me where user_id = old;
  update public.uniques set user_id = me where user_id = old;
  update public.cosmetics_owned set user_id = me where user_id = old;
  update public.blocks set placed_by = me::text where placed_by = old::text;
  update public.claims set owner = me where owner = old;
  update public.claims set members = array_replace(members, old, me) where old = any (members);
  update public.validators set owner = me where owner = old;
  update public.offers set from_user = me where from_user = old;
  update public.offers set to_user = me where to_user = old;
  update public.signs set author = me where author = old;
  update public.block_history set actor = me where actor = old;
  delete from public.recovery where user_id = me and exists (select 1 from public.recovery r where r.user_id = old);
  update public.recovery set user_id = me where user_id = old;
  delete from public.logins where user_id = me and exists (select 1 from public.logins l where l.user_id = old);
  update public.logins set user_id = me, updated_at = now() where user_id = old;
  insert into public.moved_accounts (old_id, login, at) values (old, (select login from public.logins where user_id = me), now())
    on conflict (old_id) do update set login = excluded.login, at = now();
  delete from public.moved_accounts where old_id = me; -- this device has a game again
  return n;
end $$;

-- 022's recovery by code, now through _move_account (same result, plus the offers, signs, history, login)
create or replace function public._core_claim_recovery(code text) returns integer
language plpgsql security definer set search_path = public, extensions as $$
declare old uuid; me uuid := auth.uid();
begin
  if me is null then raise exception 'not signed in'; end if;
  select user_id into old from public.recovery where code_hash = encode(extensions.digest(upper(trim(code)), 'sha256'), 'hex');
  if old is null then raise exception 'unknown code'; end if;
  if old = me then return 0; end if;
  return _move_account(old, me);
end $$;

create or replace function public._login_key(l text) returns text language sql immutable as $$ select lower(trim(l)) $$;
create or replace function public._login_ok(l text) returns boolean language sql immutable as $$
  select coalesce(trim(l) ~ '^[A-Za-z0-9_.-]{3,20}$', false) $$;

-- your login (create it, change your password, or rename it if the new one is free)
create or replace function public.act_set_login(login text, password text) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
#variable_conflict use_variable
declare me uuid := auth.uid(); k text := _login_key(login); other uuid;
begin
  if me is null then return jsonb_build_object('ok', false, 'err', 'not signed in'); end if;
  if not _rate(me, 'login', 0.2, 5) then return jsonb_build_object('ok', false, 'err', 'too many attempts'); end if;
  if not _login_ok(login) then return jsonb_build_object('ok', false, 'err', 'bad login'); end if;
  if password is null or length(password) < 6 or length(password) > 72 then
    return jsonb_build_object('ok', false, 'err', 'bad password');
  end if;
  select user_id into other from public.logins where login_key = k;
  if other is not null and other <> me then return jsonb_build_object('ok', false, 'err', 'login taken'); end if;
  delete from public.logins where user_id = me and login_key <> k; -- renamed: the old one is free again
  insert into public.logins (login_key, login, user_id, pass_hash)
    values (k, trim(login), me, extensions.crypt(password, extensions.gen_salt('bf', 10)))
    on conflict (login_key) do update set login = excluded.login, pass_hash = excluded.pass_hash, fails = 0,
      locked_until = null, updated_at = now();
  return jsonb_build_object('ok', true, 'login', trim(login));
end $$;

-- checks a login and its password; counts the wrong ones (five in a row: ten minutes locked)
create or replace function public._login_check(login text, password text) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
#variable_conflict use_variable
declare r public.logins;
begin
  select * into r from public.logins where login_key = _login_key(login) for update;
  if not found then return jsonb_build_object('ok', false, 'err', 'wrong login or password'); end if;
  if r.locked_until is not null and r.locked_until > now() then
    return jsonb_build_object('ok', false, 'err', 'locked', 'wait', ceil(extract(epoch from r.locked_until - now())));
  end if;
  if password is null or extensions.crypt(password, r.pass_hash) <> r.pass_hash then
    update public.logins set fails = case when r.fails + 1 >= 5 then 0 else r.fails + 1 end,
      locked_until = case when r.fails + 1 >= 5 then now() + interval '10 minutes' else null end
      where login_key = r.login_key;
    return jsonb_build_object('ok', false, 'err', 'wrong login or password');
  end if;
  update public.logins set fails = 0, locked_until = null where login_key = r.login_key;
  return jsonb_build_object('ok', true, 'login', r.login, 'user', r.user_id);
end $$;

-- before switching this device to a fresh session: is the password right? (nothing moves)
create or replace function public.act_check_login(login text, password text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); r jsonb;
begin
  if me is null then return jsonb_build_object('ok', false, 'err', 'not signed in'); end if;
  if not _rate(me, 'login', 0.2, 5) then return jsonb_build_object('ok', false, 'err', 'too many attempts'); end if;
  r := _login_check(login, password);
  return r - 'user';
end $$;

-- logging in: the login's game comes over to this device's session (the client opens a fresh one first)
create or replace function public.act_login(login text, password text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); r jsonb; old uuid; n integer;
begin
  if me is null then return jsonb_build_object('ok', false, 'err', 'not signed in'); end if;
  if not _rate(me, 'login', 0.2, 5) then return jsonb_build_object('ok', false, 'err', 'too many attempts'); end if;
  r := _login_check(login, password);
  if not (r ->> 'ok')::boolean then return r; end if;
  old := (r ->> 'user')::uuid;
  n := _move_account(old, me);
  return jsonb_build_object('ok', true, 'login', r ->> 'login', 'worlds', n);
end $$;

-- this session's login, if any; and if its game left for another device, the login it left with
create or replace function public.act_my_login() returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid();
begin
  if me is null then return jsonb_build_object('ok', false, 'err', 'not signed in'); end if;
  return jsonb_build_object('ok', true,
    'login', (select login from public.logins where user_id = me),
    'moved', (select coalesce(login, '') from public.moved_accounts where old_id = me));
end $$;

-- ---------- for the game's owner only, by hand ----------
create or replace function public.admin_login_info(login text) returns jsonb
language plpgsql security definer set search_path = public as $$
#variable_conflict use_variable
declare r public.logins;
begin
  select * into r from public.logins where login_key = _login_key(login);
  if not found then return jsonb_build_object('found', false); end if;
  return jsonb_build_object(
    'found', true, 'login', r.login, 'created', r.created_at, 'locked_until', r.locked_until,
    'recovery_code', exists (select 1 from public.recovery where user_id = r.user_id),
    'worlds', coalesce((select jsonb_agg(jsonb_build_object(
        'world', p.world, 'name', p.name, 'last_saved', p.updated_at, 'gwei', p.gwei,
        'items', (select coalesce(jsonb_object_agg(i.item, i.n), '{}'::jsonb) from public.inventory i where i.user_id = r.user_id and i.world = p.world and i.n > 0),
        'uniques', (select coalesce(jsonb_agg(u.item order by u.item), '[]'::jsonb) from public.uniques u where u.user_id = r.user_id and u.world = p.world),
        'claims', (select coalesce(jsonb_agg(jsonb_build_object('x', c.cx * 16 + 8, 'z', c.cz * 16 + 8)), '[]'::jsonb) from public.claims c where c.owner = r.user_id and c.world = p.world),
        'validators', (select count(*) from public.validators v where v.owner = r.user_id and v.world = p.world)))
      from public.players p where p.user_id = r.user_id), '[]'::jsonb));
end $$;

create or replace function public.admin_reset_password(login text, password text) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
#variable_conflict use_variable
begin
  if password is null or length(password) < 6 or length(password) > 72 then
    return jsonb_build_object('ok', false, 'err', 'the password needs 6 to 72 characters');
  end if;
  update public.logins set pass_hash = extensions.crypt(password, extensions.gen_salt('bf', 10)), fails = 0, locked_until = null,
    updated_at = now() where login_key = _login_key(login);
  if not found then return jsonb_build_object('ok', false, 'err', 'no such login'); end if;
  return jsonb_build_object('ok', true, 'login', (select l.login from public.logins l where l.login_key = _login_key(login)));
end $$;

-- rights: the act_ functions for the players, the internal ones and the admin ones for nobody
do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and p.proname in ('_move_account', '_core_claim_recovery', '_login_key', '_login_ok', '_login_check',
             'act_set_login', 'act_check_login', 'act_login', 'act_my_login', 'admin_login_info', 'admin_reset_password') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 4) = 'act_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
    if left(f.name, 6) = 'admin_' then execute format('revoke all on function %s from service_role', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 047_nickname_password.sql ════════════════
-- 047: you enter the game with your nickname and a password. The nickname is the login (046's logins):
-- one in the whole game, case-insensitive. A free nickname with a password makes your account; your
-- nickname with its password, on another device, brings your game there; on your usual device the
-- browser remembers you. A game started before passwords (a nickname with no login yet) gets one when
-- its player enters on that same device with a password of their choosing, or from the owner
-- (admin_set_password: a temporary password, to be changed at the first entry: must_change).
-- For the game's owner, by hand in the SQL Editor (nobody else can call them):
--   select * from admin_players();                          -- every nickname: worlds, last played, password or not
--   select * from admin_temp_passwords();                   -- a temporary password for every game that has none
--   select admin_set_password('Lucas', 'temp-4821');        -- one player (a forgotten password: check it's them)
--   select admin_player_info('Lucas');                      -- what they own, to check it's them
-- The recovery codes and 046's separate logins keep working on the server; the screen no longer offers them.
-- Requires 046_logins.sql. Replayable without error.

alter table public.logins add column if not exists must_change boolean not null default false;

-- a nickname as the players' records keep them (005_usernames.sql): latin letters, digits, space, _ . -
create or replace function public._nick_ok(n text) returns boolean language sql immutable as $$
  select coalesce(btrim(n) ~ '^[A-Za-z0-9À-ÖØ-öø-ÿ _.-]{2,20}$', false) $$;

-- entering the game. ok: you're in (login, must_change, moved: worlds brought over). Otherwise err:
-- 'wrong password' (or 'locked', with wait), 'nickname taken' (a game started before passwords, not
-- yours), 'bad nickname', 'bad password', 'fresh' (right password, but this device holds another game:
-- open a fresh session and enter again, so that game isn't overwritten), 'too many attempts'.
create or replace function public.act_enter(nick text, password text) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
#variable_conflict use_variable
declare me uuid := auth.uid(); k text := _login_key(nick); r public.logins; c jsonb; n integer;
begin
  if me is null then return jsonb_build_object('ok', false, 'err', 'not signed in'); end if;
  if not _rate(me, 'login', 0.2, 5) then return jsonb_build_object('ok', false, 'err', 'too many attempts'); end if;
  if not _nick_ok(nick) then return jsonb_build_object('ok', false, 'err', 'bad nickname'); end if;
  select * into r from public.logins where login_key = k;
  if found then
    if r.user_id <> me and (exists (select 1 from public.players where user_id = me and name is not null)
                            or exists (select 1 from public.logins where user_id = me)) then
      c := _login_check(nick, password);
      if not (c ->> 'ok')::boolean then return (c - 'user') || jsonb_build_object('err', case when c ->> 'err' = 'locked' then 'locked' else 'wrong password' end); end if;
      return jsonb_build_object('ok', false, 'err', 'fresh');
    end if;
    c := _login_check(nick, password);
    if not (c ->> 'ok')::boolean then return (c - 'user') || jsonb_build_object('err', case when c ->> 'err' = 'locked' then 'locked' else 'wrong password' end); end if;
    n := _move_account(r.user_id, me);
    return jsonb_build_object('ok', true, 'login', r.login, 'must_change', r.must_change, 'moved', n);
  end if;
  -- a nickname with no password yet: yours if no one else plays under it
  if exists (select 1 from public.players p where lower(p.name) = k and p.user_id <> me) then
    return jsonb_build_object('ok', false, 'err', 'nickname taken');
  end if;
  if exists (select 1 from public.logins where user_id = me) then return jsonb_build_object('ok', false, 'err', 'fresh'); end if;
  if password is null or length(password) < 6 or length(password) > 72 then
    return jsonb_build_object('ok', false, 'err', 'bad password');
  end if;
  insert into public.logins (login_key, login, user_id, pass_hash)
    values (k, btrim(nick), me, extensions.crypt(password, extensions.gen_salt('bf', 10)));
  return jsonb_build_object('ok', true, 'login', btrim(nick), 'must_change', false, 'created', true);
end $$;

-- your own password, changed (a temporary one included: must_change is lifted)
create or replace function public.act_set_password(password text) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
#variable_conflict use_variable
declare me uuid := auth.uid();
begin
  if me is null then return jsonb_build_object('ok', false, 'err', 'not signed in'); end if;
  if not _rate(me, 'login', 0.2, 5) then return jsonb_build_object('ok', false, 'err', 'too many attempts'); end if;
  if password is null or length(password) < 6 or length(password) > 72 then
    return jsonb_build_object('ok', false, 'err', 'bad password');
  end if;
  update public.logins set pass_hash = extensions.crypt(password, extensions.gen_salt('bf', 10)), must_change = false,
    fails = 0, locked_until = null, updated_at = now() where user_id = me;
  if not found then return jsonb_build_object('ok', false, 'err', 'no account'); end if;
  return jsonb_build_object('ok', true);
end $$;

-- 046's, plus whether your password is a temporary one
create or replace function public.act_my_login() returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid();
begin
  if me is null then return jsonb_build_object('ok', false, 'err', 'not signed in'); end if;
  return jsonb_build_object('ok', true,
    'login', (select login from public.logins where user_id = me),
    'must_change', coalesce((select must_change from public.logins where user_id = me), false),
    'moved', (select coalesce(login, '') from public.moved_accounts where old_id = me));
end $$;

-- ---------- for the game's owner only, by hand ----------
-- every nickname in the game: its worlds, when it last played, whether it has a password, and how many
-- accounts carry it (more than one: two different players, rename one before giving a password)
create or replace function public.admin_players()
returns table (nickname text, accounts bigint, worlds text, last_played timestamptz, has_password boolean, temporary boolean)
language sql stable security definer set search_path = public as $$
  select min(p.name), count(distinct p.user_id), string_agg(distinct p.world, ', '), max(p.updated_at),
         bool_or(l.user_id is not null), bool_or(coalesce(l.must_change, false))
  from public.players p left join public.logins l on l.user_id = p.user_id
  where p.name is not null
  group by lower(p.name)
  order by max(p.updated_at) desc nulls last;
$$;

-- a temporary password for one player, to be changed at their first entry
create or replace function public.admin_set_password(nick text, password text) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
#variable_conflict use_variable
declare k text := _login_key(nick); owners uuid[]; shown text;
begin
  if password is null or length(password) < 6 or length(password) > 72 then
    return jsonb_build_object('ok', false, 'err', 'the password needs 6 to 72 characters');
  end if;
  update public.logins set pass_hash = extensions.crypt(password, extensions.gen_salt('bf', 10)), must_change = true,
    fails = 0, locked_until = null, updated_at = now() where login_key = k;
  if found then return jsonb_build_object('ok', true, 'nickname', (select login from public.logins where login_key = k), 'temporary', true); end if;
  select array_agg(distinct p.user_id), min(p.name) into owners, shown from public.players p where lower(p.name) = k;
  if owners is null then return jsonb_build_object('ok', false, 'err', 'no player with this nickname'); end if;
  if array_length(owners, 1) > 1 then
    return jsonb_build_object('ok', false, 'err', 'two different accounts carry this nickname: rename one first',
      'worlds', (select jsonb_agg(jsonb_build_object('world', p.world, 'account', p.user_id)) from public.players p where lower(p.name) = k));
  end if;
  if exists (select 1 from public.logins where user_id = owners[1]) then
    return jsonb_build_object('ok', false, 'err', 'this account already has a login: ' || (select login from public.logins where user_id = owners[1]));
  end if;
  insert into public.logins (login_key, login, user_id, pass_hash, must_change)
    values (k, btrim(shown), owners[1], extensions.crypt(password, extensions.gen_salt('bf', 10)), true);
  return jsonb_build_object('ok', true, 'nickname', btrim(shown), 'temporary', true);
end $$;

-- a temporary password for every game that has none yet: the list to send to each player (a nickname
-- carried by two accounts is left out, with a word about it)
create or replace function public.admin_temp_passwords()
returns table (nickname text, temporary_password text, worlds text, note text)
language plpgsql security definer set search_path = public, extensions as $$
declare g record; pw text; r jsonb;
begin
  for g in select lower(p.name) as k, min(p.name) as name, string_agg(distinct p.world, ', ') as worlds
           from public.players p
           where p.name is not null and not exists (select 1 from public.logins l where l.user_id = p.user_id)
             and not exists (select 1 from public.logins l where l.login_key = lower(p.name))
           group by lower(p.name) order by min(p.name) loop
    pw := 'ether-' || substr(encode(extensions.gen_random_bytes(4), 'hex'), 1, 6);
    r := admin_set_password(g.name, pw);
    nickname := g.name;
    worlds := g.worlds;
    if (r ->> 'ok')::boolean then
      temporary_password := pw;
      note := 'to change at the first entry';
    else
      temporary_password := null;
      note := r ->> 'err';
    end if;
    return next;
  end loop;
end $$;

-- what a player owns, by nickname (with or without a password), to check a request is really theirs
create or replace function public.admin_player_info(nick text) returns jsonb
language plpgsql security definer set search_path = public as $$
#variable_conflict use_variable
declare k text := _login_key(nick);
begin
  return coalesce((select jsonb_agg(jsonb_build_object(
      'account', a.uid,
      'password', exists (select 1 from public.logins l where l.user_id = a.uid),
      'worlds', (select jsonb_agg(jsonb_build_object(
          'world', p.world, 'name', p.name, 'last_saved', p.updated_at, 'gwei', p.gwei,
          'items', (select coalesce(jsonb_object_agg(i.item, i.n), '{}'::jsonb) from public.inventory i where i.user_id = a.uid and i.world = p.world and i.n > 0),
          'uniques', (select coalesce(jsonb_agg(u.item order by u.item), '[]'::jsonb) from public.uniques u where u.user_id = a.uid and u.world = p.world),
          'claims', (select coalesce(jsonb_agg(jsonb_build_object('x', c.cx * 16 + 8, 'z', c.cz * 16 + 8)), '[]'::jsonb) from public.claims c where c.owner = a.uid and c.world = p.world),
          'validators', (select count(*) from public.validators v where v.owner = a.uid and v.world = p.world)))
        from public.players p where p.user_id = a.uid)))
    from (select distinct p.user_id as uid from public.players p where lower(p.name) = k
          union select l.user_id from public.logins l where l.login_key = k) a), '[]'::jsonb);
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and p.proname in ('_nick_ok', 'act_enter', 'act_set_password', 'act_my_login',
             'admin_players', 'admin_set_password', 'admin_temp_passwords', 'admin_player_info') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 4) = 'act_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
    if left(f.name, 6) = 'admin_' then execute format('revoke all on function %s from service_role', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 048_claim_price.sql ════════════════
-- 048: a plot costs Gwei, more for each one you hold: 500 for the first, then twice as much each time
-- (1 000, 2 000, 4 000...), and 9 plots at most in a world. Holding a stretch of land is something a
-- player works for, and can't be done by the dozen to block the others. Plots already held stay; giving
-- one up (unclaim) brings the next price down again, nothing is refunded. Replaces 001's 2 Ether Crystals
-- and 16 plots. Requires 001_schema.sql, 019_gwei_currency.sql, 028_leaderboard.sql. Replayable.
create or replace function public._claim_price(n integer) returns bigint language sql immutable as $$
  select (500 * power(2, greatest(n, 0)))::bigint $$;

create or replace function public._core_claim(w text, qx int, qz int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); pl players; held integer; price bigint;
begin
  pl := _player(me, w);
  if qx = 0 and qz = 0 then return _no('the sanctuary belongs to everyone'); end if;
  if abs(qx) > 6250 or abs(qz) > 6250 then return _no('out of the world'); end if;
  if exists (select 1 from claims where world = w and cx = qx and cz = qz) then return _no('already claimed'); end if;
  select count(*) into held from claims where world = w and owner = me;
  if held >= 9 then return _no('9 plots at most'); end if;
  price := _claim_price(held);
  if coalesce(pl.gwei, 0) < price then return jsonb_build_object('ok', false, 'err', 'needs ' || price || ' gwei', 'price', price); end if;
  perform _gwei(me, w, -price);
  insert into claims (world, cx, cz, owner, owner_name, members)
    select w, qx, qz, me, pl.name, coalesce((select members from claims where world = w and owner = me limit 1), '{}');
  return jsonb_build_object('ok', true, 'inv', '{}'::jsonb, 'gwei', price, 'total_gwei', _gwei_balance(me, w),
    'next_price', case when held + 1 >= 9 then null else _claim_price(held + 1) end);
end $$;

revoke all on function public._claim_price(integer) from public, anon, authenticated;
revoke all on function public._core_claim(text, int, int) from public, anon, authenticated;

-- ════════════════ 049_biome_mobs.sql ════════════════
-- 049: the surface's own mobs, one per biome (src/mobs-core.js MK, spawnChunk): the Gas Scorpion of the dunes,
-- the Phishing Spider of the forests, the Pump Slime of the plains and the Cold Wallet Yeti of the snowy peaks.
-- Their loot joins the common table of _loot_mob; everything else is 041's, unchanged (the function is
-- replaced whole). Requires 041_game_server.sql. Replayable without error.

-- the loot of a kill, for one player (check_pos: their reported position must match the one on record)
create or replace function public._loot_mob(me uuid, w text, mob_type text, ex real, ey real, ez real, check_pos boolean) returns jsonb
language plpgsql security definer set search_path = public as $$
declare e text; it int; inv jsonb := '{}'; r real; u jsonb; cid smallint; g int; bonus jsonb; aw record; sh int;
begin
  -- 030: the Merge twins, reported once, when both fall together — a guaranteed Merge Aegis, ~20% a bonus
  if mob_type = 'merge_twins' then
    if not _rate(me, 'loot_boss', 0.05, 1) then return _no('too many actions'); end if;
    if check_pos then e := _check_pos(me, w, ex, ey, ez); end if;
    if e is not null then return _no(e); end if;
    u := _mint(me, w, 209, null);
    if random() < 0.2 then bonus := _mint(me, w, 210, null); end if;
    sh := 2;                                                    -- 037: two Diamond Shards, both twins down
    inv := _give(me, w, 110, sh, inv);
    return jsonb_build_object('ok', true, 'inv', inv, 'unique', u, 'bonus', bonus, 'shards', sh);
  end if;
  -- 039: the Front-Runner, the Mempool's boss: guaranteed Front-Runner Boots, ~20% a Flashbots Bundle,
  -- two Diamond Shards; the same loot_boss rate limit as every other boss
  if mob_type = 'front_runner' then
    if not _rate(me, 'loot_boss', 0.05, 1) then return _no('too many actions'); end if;
    if check_pos then e := _check_pos(me, w, ex, ey, ez); end if;
    if e is not null then return _no(e); end if;
    u := _mint(me, w, 211, null);
    if random() < 0.2 then bonus := _mint(me, w, 212, null); end if;
    sh := 2;
    inv := _give(me, w, 110, sh, inv);
    return jsonb_build_object('ok', true, 'inv', inv, 'unique', u, 'bonus', bonus, 'shards', sh);
  end if;
  if mob_type = 'corrupted_node' then
    if not _rate(me, 'attack_node', 0.3, 6) then return _no('too many actions'); end if;
    if check_pos then e := _check_pos(me, w, ex, ey, ez); end if;
    if e is not null then return _no(e); end if;
    if sqrt((ex - 8) ^ 2 + (ez - 8) ^ 2) > 30 then return _no('too far from the Atrium'); end if;
    select * into aw from _attack_window();
    if not aw.active then return _no('no attack right now'); end if;
    insert into network_events (world, window_id, kills, participants) values (w, aw.window_id, 1, jsonb_build_object(me::text, 1))
      on conflict (world, window_id) do update set kills = network_events.kills + 1,
        participants = network_events.participants || jsonb_build_object(me::text, coalesce((network_events.participants ->> me::text)::int, 0) + 1);
    r := random();
    if r < 0.08 then
      select id into cid from rule_cosmetics where category = 'event'
        and id not in (select cosmetic_id from cosmetics_owned where user_id = me and world = w) order by random() limit 1;
      if cid is not null then
        insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, cid);
        return jsonb_build_object('ok', true, 'inv', inv, 'cosmetic', cid);
      end if;
    elsif r < 0.33 then
      g := 10 + floor(random() * 41)::int;
      perform _gwei(me, w, g);
      return jsonb_build_object('ok', true, 'inv', inv, 'gwei', g, 'total_gwei', _gwei_balance(me, w));
    end if;
    inv := _give(me, w, 101, 1 + floor(random() * 2)::int, inv); -- no whiffed kills during the event: a guaranteed small bundle
    return jsonb_build_object('ok', true, 'inv', inv);
  end if;
  if mob_type in ('titan', 'plasma_core') then
    if not _rate(me, 'loot_boss', 0.05, 1) then return _no('too many actions'); end if;
    if check_pos then e := _check_pos(me, w, ex, ey, ez); end if;
    if e is not null then return _no(e); end if;
    u := _mint(me, w, case when mob_type = 'titan' then 205 else 206 end, null);
    if random() < 0.2 then
      bonus := _mint(me, w, case when mob_type = 'titan' then 207 else 208 end, null);
    end if;
    sh := 1 + floor(random() * 2)::int;                         -- 037: one or two Diamond Shards
    inv := _give(me, w, 110, sh, inv);
    return jsonb_build_object('ok', true, 'inv', inv, 'unique', u, 'bonus', bonus, 'shards', sh);
  end if;
  if not _rate(me, 'loot_mob', 0.2, 5) then return _no('too many actions'); end if;
  if check_pos then e := _check_pos(me, w, ex, ey, ez); end if;
  if e is not null then return _no(e); end if;
  -- epic (~3%): a combat-exclusive cosmetic the player doesn't already own; falls through to the
  -- common table once every combat cosmetic is collected. rare (~12%): a small Gwei bonus.
  r := random();
  if r < 0.03 then
    select id into cid from rule_cosmetics where category = 'combat'
      and id not in (select cosmetic_id from cosmetics_owned where user_id = me and world = w)
      order by random() limit 1;
    if cid is not null then
      insert into cosmetics_owned (user_id, world, cosmetic_id) values (me, w, cid);
      return jsonb_build_object('ok', true, 'inv', inv, 'cosmetic', cid);
    end if;
  elsif r < 0.15 then
    g := 10 + floor(random() * 41)::int; -- 10..50
    perform _gwei(me, w, g);
    return jsonb_build_object('ok', true, 'inv', inv, 'gwei', g, 'total_gwei', _gwei_balance(me, w));
  end if;
  -- common (unchanged): the existing per-mob-type resource chance, its own independent roll
  r := random();
  it := case mob_type
    when 'shadow' then case when r < 0.5 then 101 end
    when 'guardian' then case when r < 0.35 then 101 when r < 0.5 then 103 end
    when 'sentinel' then case when r < 0.4 then 103 end
    when 'wraith' then case when r < 0.25 then 104 when r < 0.65 then 103 end
    when 'warden' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'garden_guardian' then case when r < 0.35 then 101 when r < 0.5 then 103 end
    when 'prowler' then case when r < 0.5 then 101 end
    when 'sky_raider' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'water_lurker' then case when r < 0.25 then 103 when r < 0.5 then 104 end
    when 'bat' then case when r < 0.45 then 101 end
    when 'crawler' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    when 'golem' then case when r < 0.3 then 103 when r < 0.55 then 104 end
    when 'mev_bot' then case when r < 0.5 then 101 end                -- 039: the Front-Runner's Sandwich Bots
    when 'gas_scorpion' then case when r < 0.35 then 101 when r < 0.5 then 103 end  -- 049: the surface's biome mobs
    when 'phish_spider' then case when r < 0.45 then 101 end
    when 'pump_slime' then case when r < 0.55 then 101 end
    when 'yeti' then case when r < 0.3 then 103 when r < 0.55 then 104 end
    else null
  end;
  if it is null then return jsonb_build_object('ok', true, 'inv', inv); end if;
  inv := _give(me, w, it, 1, inv);
  return jsonb_build_object('ok', true, 'inv', inv, 'item', it);
end $$;

revoke all on function public._loot_mob(uuid, text, text, real, real, real, boolean) from public, anon, authenticated;

-- ════════════════ 050_purchases.sql ════════════════
-- 050: buying the premium pieces with real money, through Stripe (the "checkout" and "stripe-webhook" Edge
-- Functions). The player asks for a piece (srv_premium_quote: a premium piece, not owned yet, and an account
-- with a password, so the purchase can follow them to another device); Stripe Checkout takes the payment;
-- Stripe's signed webhook tells us it went through (srv_premium_paid) or was refunded (srv_premium_refunded).
-- A paid piece belongs to the account in every world (act_premium_owned), unlike the Gwei pieces, which
-- belong to one world.
-- The purchases live in their own schema, billing, which reset.sql leaves alone: real money is never wiped
-- with a season. Each row keeps the nickname and the buyer's email, so a purchase can be found again by hand
-- after a reset. Stripe's test mode (livemode false) only counts outside the players' world, 'principal'.
-- Only the service key (the Edge Functions) writes here. Requires 022, 046, 047. Replayable without error.

alter table public.rule_cosmetics add column if not exists eur integer; -- price in euro cents, premium only

create schema if not exists billing;
revoke all on schema billing from public, anon, authenticated;

create table if not exists billing.purchases (
  id             bigserial   primary key,
  user_id        uuid        not null,               -- no foreign key: the row outlives the account
  nick           text        not null,
  cosmetic_id    smallint    not null,
  eur            integer     not null,               -- cents, as charged
  livemode       boolean     not null default false, -- false: Stripe's test mode
  status         text        not null default 'pending' check (status in ('pending', 'paid', 'refunded')),
  stripe_session text        not null unique,
  stripe_payment text,                               -- the payment intent, what a refund points to
  email          text,
  created_at     timestamptz not null default now(),
  paid_at        timestamptz,
  refunded_at    timestamptz
);
-- a second lock on top of the schema's: no policy, so only the functions below (run as the owner) see it
alter table billing.purchases enable row level security;
create index if not exists purchases_user on billing.purchases (user_id);
create index if not exists purchases_payment on billing.purchases (stripe_payment);

-- the premium pieces an account owns, for one world (test purchases only count outside 'principal')
create or replace function public.act_premium_owned(w text) returns smallint[]
language sql security definer set search_path = public, billing stable as $$
  select coalesce(array_agg(distinct cosmetic_id order by cosmetic_id), '{}')
  from billing.purchases where user_id = auth.uid() and status = 'paid' and (livemode or w <> 'principal')
$$;

-- before opening a payment: what to charge, or why not
create or replace function public.srv_premium_quote(p_user uuid, cid int, live boolean, w text) returns jsonb
language plpgsql security definer set search_path = public, billing as $$
declare rc rule_cosmetics; nk text;
begin
  if not _rate(p_user, 'premium_checkout', 0.1, 5) then return _no('too many actions'); end if;
  select * into rc from rule_cosmetics where id = cid;
  if not found or rc.category <> 'premium' or coalesce(rc.eur, 0) <= 0 then return _no('not for sale'); end if;
  if not live and w = 'principal' then return _no('test payments only in test worlds'); end if;
  select login into nk from logins where user_id = p_user;
  if nk is null then return _no('set a password first'); end if;
  if exists (select 1 from billing.purchases where user_id = p_user and cosmetic_id = cid and status = 'paid' and livemode = live) then
    return _no('already owned');
  end if;
  return jsonb_build_object('ok', true, 'eur', rc.eur, 'name', rc.name, 'nick', nk);
end $$;

-- the Checkout session is open: remember it, so the webhook can match it
create or replace function public.srv_premium_pending(p_user uuid, cid int, eur_ int, live boolean, session text) returns void
language sql security definer set search_path = public, billing as $$
  insert into billing.purchases (user_id, nick, cosmetic_id, eur, livemode, stripe_session)
  values (p_user, coalesce((select login from logins where user_id = p_user), '?'), cid, eur_, live, session)
  on conflict (stripe_session) do nothing
$$;

-- Stripe says the session was paid (signed webhook). Safe to receive twice. The amount must be the one asked
-- for; a session we never recorded (lost reply) is taken from the session's own metadata.
create or replace function public.srv_premium_paid(session text, payment text, mail text, amount int, live boolean, p_user uuid, cid int) returns jsonb
language plpgsql security definer set search_path = public, billing as $$
declare p billing.purchases;
begin
  select * into p from billing.purchases where stripe_session = session for update;
  if not found then
    if p_user is null or cid is null then return _no('unknown session'); end if;
    insert into billing.purchases (user_id, nick, cosmetic_id, eur, livemode, stripe_session)
    values (p_user, coalesce((select login from logins where user_id = p_user), '?'), cid, amount, live, session)
    returning * into p;
  end if;
  if p.status = 'paid' then return jsonb_build_object('ok', true, 'already', true); end if;
  if p.status = 'refunded' then return _no('refunded'); end if;
  if amount is distinct from p.eur then return _no('wrong amount'); end if;
  update billing.purchases set status = 'paid', paid_at = now(), stripe_payment = payment, email = mail, livemode = live
  where id = p.id;
  return jsonb_build_object('ok', true, 'cosmetic', p.cosmetic_id, 'user', p.user_id);
end $$;

-- a full refund (or a lost dispute) takes the piece back
create or replace function public.srv_premium_refunded(payment text) returns jsonb
language plpgsql security definer set search_path = public, billing as $$
declare n int;
begin
  update billing.purchases set status = 'refunded', refunded_at = now() where stripe_payment = payment and status = 'paid';
  get diagnostics n = row_count;
  return jsonb_build_object('ok', true, 'refunded', n);
end $$;

-- 046's account move (entering with your nickname on another device) now also carries the purchases.
-- Same function as 046, plus the billing line.
create or replace function public._move_account(old uuid, me uuid) returns integer
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  if old is null or me is null or old = me then return 0; end if;
  delete from public.inventory i where i.user_id = me and exists (select 1 from public.players o where o.user_id = old and o.world = i.world);
  delete from public.uniques u where u.user_id = me and exists (select 1 from public.players o where o.user_id = old and o.world = u.world);
  delete from public.cosmetics_owned c where c.user_id = me and exists (select 1 from public.players o where o.user_id = old and o.world = c.world);
  delete from public.players p where p.user_id = me and exists (select 1 from public.players o where o.user_id = old and o.world = p.world);
  update public.players set user_id = me where user_id = old;
  get diagnostics n = row_count;
  update public.inventory set user_id = me where user_id = old;
  update public.uniques set user_id = me where user_id = old;
  update public.cosmetics_owned set user_id = me where user_id = old;
  update billing.purchases set user_id = me where user_id = old;
  update public.blocks set placed_by = me::text where placed_by = old::text;
  update public.claims set owner = me where owner = old;
  update public.claims set members = array_replace(members, old, me) where old = any (members);
  update public.validators set owner = me where owner = old;
  update public.offers set from_user = me where from_user = old;
  update public.offers set to_user = me where to_user = old;
  update public.signs set author = me where author = old;
  update public.block_history set actor = me where actor = old;
  delete from public.recovery where user_id = me and exists (select 1 from public.recovery r where r.user_id = old);
  update public.recovery set user_id = me where user_id = old;
  delete from public.logins where user_id = me and exists (select 1 from public.logins l where l.user_id = old);
  update public.logins set user_id = me, updated_at = now() where user_id = old;
  insert into public.moved_accounts (old_id, login, at) values (old, (select login from public.logins where user_id = me), now())
    on conflict (old_id) do update set login = excluded.login, at = now();
  delete from public.moved_accounts where old_id = me; -- this device has a game again
  return n;
end $$;

-- rights: act_premium_owned for the players, the srv_ ones for the service key only, _move_account for nobody
revoke all on function public.act_premium_owned(text) from public, anon, authenticated;
grant execute on function public.act_premium_owned(text) to authenticated;
revoke all on function public._move_account(uuid, uuid) from public, anon, authenticated;
revoke all on function public.srv_premium_quote(uuid, int, boolean, text) from public, anon, authenticated;
revoke all on function public.srv_premium_pending(uuid, int, int, boolean, text) from public, anon, authenticated;
revoke all on function public.srv_premium_paid(text, text, text, int, boolean, uuid, int) from public, anon, authenticated;
revoke all on function public.srv_premium_refunded(text) from public, anon, authenticated;
grant execute on function public.srv_premium_quote(uuid, int, boolean, text) to service_role;
grant execute on function public.srv_premium_pending(uuid, int, int, boolean, text) to service_role;
grant execute on function public.srv_premium_paid(text, text, text, int, boolean, uuid, int) to service_role;
grant execute on function public.srv_premium_refunded(text) to service_role;

-- ════════════════ 051_premium_sets.sql ════════════════
-- 051: a premium collection bought whole, for less than its pieces (rules.js SET_EUR, setPrice). Owning
-- some pieces already, you pay the same share of the set's price as the share of the pieces you're missing.
-- One Stripe session, one purchases row listing its pieces (pieces); a refund takes them all back. 050's
-- single pieces now also count as owned when they came in a set. Requires 050_purchases.sql. Replayable.

alter table public.rule_cosmetics add column if not exists set_id text; -- premium pieces only
create table if not exists public.rule_sets (
  id  text    primary key,
  eur integer not null -- the whole set, euro cents
);
alter table public.rule_sets enable row level security;
drop policy if exists "read rule_sets" on public.rule_sets;
create policy "read rule_sets" on public.rule_sets for select using (true);

alter table billing.purchases alter column cosmetic_id drop not null;   -- null for a set
alter table billing.purchases add column if not exists set_id text;
alter table billing.purchases add column if not exists pieces smallint[]; -- a set's pieces, as bought

-- the premium pieces an account has paid for (live ones only, or test ones too)
create or replace function public._premium_has(p_user uuid, with_test boolean) returns smallint[]
language sql security definer set search_path = public, billing stable as $$
  select coalesce(array_agg(distinct c order by c), '{}')
  from billing.purchases p, unnest(coalesce(p.pieces, array[p.cosmetic_id])) c
  where p.user_id = p_user and p.status = 'paid' and (p.livemode or with_test)
$$;

create or replace function public.act_premium_owned(w text) returns smallint[]
language sql security definer set search_path = public, billing stable as $$
  select _premium_has(auth.uid(), w <> 'principal')
$$;

-- one piece: as in 050, but a piece that came in a set is owned too (a test purchase only counts for test)
create or replace function public.srv_premium_quote(p_user uuid, cid int, live boolean, w text) returns jsonb
language plpgsql security definer set search_path = public, billing as $$
declare rc rule_cosmetics; nk text;
begin
  if not _rate(p_user, 'premium_checkout', 0.1, 5) then return _no('too many actions'); end if;
  select * into rc from rule_cosmetics where id = cid;
  if not found or rc.category <> 'premium' or coalesce(rc.eur, 0) <= 0 then return _no('not for sale'); end if;
  if not live and w = 'principal' then return _no('test payments only in test worlds'); end if;
  select login into nk from logins where user_id = p_user;
  if nk is null then return _no('set a password first'); end if;
  if cid = any (_premium_has(p_user, not live)) then return _no('already owned'); end if;
  return jsonb_build_object('ok', true, 'eur', rc.eur, 'name', rc.name, 'nick', nk);
end $$;

-- a whole set: the pieces still missing, and the share of the set's price they're worth
create or replace function public.srv_premium_quote_set(p_user uuid, set_ text, live boolean, w text) returns jsonb
language plpgsql security definer set search_path = public, billing as $$
declare rs rule_sets; nk text; have smallint[]; missing smallint[]; full_ int; part int;
begin
  if not _rate(p_user, 'premium_checkout', 0.1, 5) then return _no('too many actions'); end if;
  select * into rs from rule_sets where id = set_;
  if not found then return _no('not for sale'); end if;
  if not live and w = 'principal' then return _no('test payments only in test worlds'); end if;
  select login into nk from logins where user_id = p_user;
  if nk is null then return _no('set a password first'); end if;
  have := _premium_has(p_user, not live);
  select coalesce(sum(eur), 0), coalesce(sum(eur) filter (where not (id = any (have))), 0),
         coalesce(array_agg(id order by id) filter (where not (id = any (have))), '{}')
    into full_, part, missing
    from rule_cosmetics where set_id = set_ and category = 'premium';
  if full_ = 0 then return _no('not for sale'); end if;
  if cardinality(missing) = 0 then return _no('already owned'); end if;
  return jsonb_build_object('ok', true, 'eur', round(rs.eur::numeric * part / full_)::int, 'pieces', to_jsonb(missing), 'nick', nk);
end $$;

create or replace function public.srv_premium_pending_set(p_user uuid, set_ text, pieces_ smallint[], eur_ int, live boolean, session text) returns void
language sql security definer set search_path = public, billing as $$
  insert into billing.purchases (user_id, nick, set_id, pieces, eur, livemode, stripe_session)
  values (p_user, coalesce((select login from logins where user_id = p_user), '?'), set_, pieces_, eur_, live, session)
  on conflict (stripe_session) do nothing
$$;

-- 050's, plus a set rebuilt from the session's metadata when we never recorded it (lost reply)
drop function if exists public.srv_premium_paid(text, text, text, int, boolean, uuid, int);
create or replace function public.srv_premium_paid(session text, payment text, mail text, amount int, live boolean, p_user uuid, cid int,
  set_ text default null, pieces_ smallint[] default null) returns jsonb
language plpgsql security definer set search_path = public, billing as $$
declare p billing.purchases;
begin
  select * into p from billing.purchases where stripe_session = session for update;
  if not found then
    if p_user is null or (cid is null and pieces_ is null) then return _no('unknown session'); end if;
    insert into billing.purchases (user_id, nick, cosmetic_id, set_id, pieces, eur, livemode, stripe_session)
    values (p_user, coalesce((select login from logins where user_id = p_user), '?'), case when pieces_ is null then cid end,
            set_, pieces_, amount, live, session)
    returning * into p;
  end if;
  if p.status = 'paid' then return jsonb_build_object('ok', true, 'already', true); end if;
  if p.status = 'refunded' then return _no('refunded'); end if;
  if amount is distinct from p.eur then return _no('wrong amount'); end if;
  update billing.purchases set status = 'paid', paid_at = now(), stripe_payment = payment, email = mail, livemode = live
  where id = p.id;
  return jsonb_build_object('ok', true, 'cosmetic', p.cosmetic_id, 'pieces', p.pieces, 'user', p.user_id);
end $$;

revoke all on function public._premium_has(uuid, boolean) from public, anon, authenticated;
revoke all on function public.act_premium_owned(text) from public, anon, authenticated;
grant execute on function public.act_premium_owned(text) to authenticated;
revoke all on function public.srv_premium_quote(uuid, int, boolean, text) from public, anon, authenticated;
revoke all on function public.srv_premium_quote_set(uuid, text, boolean, text) from public, anon, authenticated;
revoke all on function public.srv_premium_pending_set(uuid, text, smallint[], int, boolean, text) from public, anon, authenticated;
revoke all on function public.srv_premium_paid(text, text, text, int, boolean, uuid, int, text, smallint[]) from public, anon, authenticated;
grant execute on function public.srv_premium_quote(uuid, int, boolean, text) to service_role;
grant execute on function public.srv_premium_quote_set(uuid, text, boolean, text) to service_role;
grant execute on function public.srv_premium_pending_set(uuid, text, smallint[], int, boolean, text) to service_role;
grant execute on function public.srv_premium_paid(text, text, text, int, boolean, uuid, int, text, smallint[]) to service_role;

-- ════════════════ 052_store_purchases.sql ════════════════
-- 052: the premium pieces and sets bought in the apps, through the App Store or Google Play (the "iap-verify"
-- Edge Function checks each purchase with Apple's or Google's own server first). They land in 050's
-- billing.purchases, beside Stripe's, and count the same (act_premium_owned): bought anywhere, worn
-- everywhere. A store purchase is keyed by its store and transaction ('apple:<originalTransactionId>',
-- 'google:<orderId>') in stripe_session, the column that keeps each purchase once; refunds point to the same
-- key through stripe_payment. In the apps a set is sold whole, at its full price. Requires 050, 051. Replayable.

alter table billing.purchases add column if not exists store text not null default 'stripe' check (store in ('stripe', 'apple', 'google'));

-- a store purchase Apple or Google confirmed. Safe to receive twice (restoring purchases on a new device sends
-- them all again): already recorded for this account, nothing changes; recorded for another account, it stays
-- theirs (one Apple or Google account shared by two players doesn't hand over what one of them paid for).
create or replace function public.srv_store_paid(p_user uuid, store_ text, tx text, cid int, set_ text, live boolean, w text) returns jsonb
language plpgsql security definer set search_path = public, billing as $$
declare key text := store_ || ':' || tx; p billing.purchases; rc rule_cosmetics; rs rule_sets; pcs smallint[]; nk text;
begin
  if store_ not in ('apple', 'google') or coalesce(tx, '') = '' then return _no('invalid purchase'); end if;
  if not _rate(p_user, 'premium_store', 0.5, 20) then return _no('too many actions'); end if;
  if not live and w = 'principal' then return _no('test payments only in test worlds'); end if;
  select login into nk from logins where user_id = p_user;
  if nk is null then return _no('set a password first'); end if;
  select * into p from billing.purchases where stripe_session = key;
  if found then
    if p.user_id <> p_user then return _no('bought by another account'); end if;
    if p.status = 'refunded' then return _no('refunded'); end if;
    return jsonb_build_object('ok', true, 'already', true, 'pieces', to_jsonb(coalesce(p.pieces, array[p.cosmetic_id])));
  end if;
  if set_ is not null then
    select * into rs from rule_sets where id = set_;
    if not found then return _no('not for sale'); end if;
    select coalesce(array_agg(id order by id), '{}') into pcs from rule_cosmetics where set_id = set_ and category = 'premium';
    if cardinality(pcs) = 0 then return _no('not for sale'); end if;
    insert into billing.purchases (user_id, nick, set_id, pieces, eur, livemode, status, stripe_session, stripe_payment, store, paid_at)
    values (p_user, nk, set_, pcs, rs.eur, live, 'paid', key, key, store_, now());
  else
    select * into rc from rule_cosmetics where id = cid;
    if not found or rc.category <> 'premium' or coalesce(rc.eur, 0) <= 0 then return _no('not for sale'); end if;
    pcs := array[rc.id];
    insert into billing.purchases (user_id, nick, cosmetic_id, eur, livemode, status, stripe_session, stripe_payment, store, paid_at)
    values (p_user, nk, rc.id, rc.eur, live, 'paid', key, key, store_, now());
  end if;
  return jsonb_build_object('ok', true, 'pieces', to_jsonb(pcs));
end $$;

-- Apple or Google says a purchase was refunded: the piece (or the set) goes, as with Stripe
create or replace function public.srv_store_refunded(store_ text, tx text) returns jsonb
language sql security definer set search_path = public, billing as $$
  select srv_premium_refunded(store_ || ':' || tx)
$$;

revoke all on function public.srv_store_paid(uuid, text, text, int, text, boolean, text) from public, anon, authenticated;
revoke all on function public.srv_store_refunded(text, text) from public, anon, authenticated;
grant execute on function public.srv_store_paid(uuid, text, text, int, text, boolean, text) to service_role;
grant execute on function public.srv_store_refunded(text, text) to service_role;

-- ════════════════ 053_play_days.sql ════════════════
-- 053: who comes back. Each day a player enters a world, one row (act_seen, called by the game when you
-- enter: the web, the apps), keyed by their nickname so a game moved to another device stays one player.
-- The views below answer the launch's only question: of the players who came for the first time on a
-- day, how many came back the next day (D1) and a week later (D7), by platform. They are read by hand in
-- Supabase's SQL Editor (select * from public.retention_summary), never by the game: no access for anon or
-- authenticated. Nothing here moves value. Wiped by reset.sql. Replayable.

create table if not exists public.play_days (
  world    text not null,
  who      text not null,            -- the nickname, lowercased (or the account id before one is chosen)
  day      date not null,            -- UTC
  platform text not null,            -- web, web-mobile, ios, android, mac, pc, editor, other
  primary key (world, who, day)
);
alter table public.play_days enable row level security; -- no policy: only the functions below write it

create or replace function public.act_seen(w text, platform text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  nm text;
  p text := case when platform in ('web', 'web-mobile', 'ios', 'android', 'mac', 'pc', 'editor') then platform else 'other' end;
begin
  if me is null or w is null then return jsonb_build_object('ok', false); end if;
  if not _rate(me, 'seen', 0.2, 5) then return jsonb_build_object('ok', false); end if;
  select lower(name) into nm from players where user_id = me and world = w;
  insert into play_days (world, who, day, platform)
  values (w, coalesce(nm, me::text), (now() at time zone 'utc')::date, p)
  on conflict (world, who, day) do nothing;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.act_seen(text, text) from public;
grant execute on function public.act_seen(text, text) to authenticated, anon;

-- by first day and platform (the one they first came on): how many, and how many came back on day 1 and day 7
create or replace view public.retention as
with firsts as (
  select distinct on (world, who) world, who, day as d0, platform
  from play_days order by world, who, day
)
select f.world, f.d0 as first_day, f.platform, count(*) as players,
  count(*) filter (where exists (select 1 from play_days x where x.world = f.world and x.who = f.who and x.day = f.d0 + 1)) as came_back_d1,
  count(*) filter (where exists (select 1 from play_days x where x.world = f.world and x.who = f.who and x.day = f.d0 + 7)) as came_back_d7
from firsts f
group by f.world, f.d0, f.platform;

-- everything at once, by platform, in percent: only the first days old enough to count (D1 needs a day
-- after, D7 a week after)
create or replace view public.retention_summary as
select world, platform, sum(players) as players,
  round(100.0 * sum(came_back_d1) filter (where first_day <= current_date - 1) / nullif(sum(players) filter (where first_day <= current_date - 1), 0), 1) as d1_percent,
  round(100.0 * sum(came_back_d7) filter (where first_day <= current_date - 7) / nullif(sum(players) filter (where first_day <= current_date - 7), 0), 1) as d7_percent
from public.retention
group by world, platform
order by world, players desc;

revoke all on public.retention, public.retention_summary from anon, authenticated;

-- ════════════════ 054_three_validators.sql ════════════════
-- 054: three validators at most per player and world. Relighting a fourth ruin is refused; the ruins stay
-- for the others. Same _core_relight as 020_validators.sql, with only the count added. The players who already
-- run more keep them until the launch's clean-up (tools/launch-cleanup.sql keeps each player's three rarest).
-- Requires 020_validators.sql. Replayable without error.

create or replace function public._core_relight(w text, px int, py int, pz int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); pl players; inv jsonb := '{}'; s int; ch jsonb := '[]'; u jsonb; star jsonb; solid boolean;
        relit_n int; shard boolean := false; rarity text; stats jsonb; vid bigint;
begin
  pl := _player(me, w);
  if _cell(w, px, py, pz) <> 73 then return _no('not a dark validator', jsonb_build_object('cell', _cell(w, px, py, pz))); end if;
  for i in 0..2 loop
    solid := coalesce((select rb.solid from rule_blocks rb where rb.id = _cell_soft(w, px + 2, py + i, pz + 2)), false);
    if not solid then return _no('rebuild the fourth column first'); end if;
  end loop;
  -- three at most per player (whatever their state): a fourth ruin stays for someone else
  if (select count(*) from validators v where v.world = w and v.owner = me) >= 3 then
    return _no('three validators at most');
  end if;
  if _count(me, w, 105) < 1 then return _no('needs a validator heart'); end if;
  inv := _give(me, w, 105, -1, inv);
  update players set serial = serial + 1 where user_id = me and world = w returning serial into s;
  ch := ch || _set(w, px, py, pz, 74, me, pl.name, s);
  rarity := _pick_rarity();
  stats := _validator_stats(rarity, 1);
  insert into validators (world, x, y, z, owner, owner_name, state, rarity, level, gwei_per_cycle, maintenance_cost, reanimated_at, last_cycle_at)
    values (w, px, py, pz, me, pl.name, 'active', rarity, 1, (stats ->> 'gwei_per_cycle')::int, (stats ->> 'maintenance_cost')::int, now(), now())
    on conflict (world, x, y, z) do update set owner = excluded.owner, owner_name = excluded.owner_name, state = 'active',
      rarity = excluded.rarity, level = 1, gwei_per_cycle = excluded.gwei_per_cycle, maintenance_cost = excluded.maintenance_cost,
      missed_cycles = 0, reanimated_at = now(), last_cycle_at = now()
    returning id into vid;
  u := _mint(me, w, 203, px || ', ' || py || ', ' || pz);
  update uniques set validator_id = vid where user_id = me and world = w and serial = (u ->> 'serial')::int;
  select count(*) into relit_n from blocks where world = w and id = 74;
  if relit_n = any (array[3, 10, 25, 50, 100]) then
    star := _mint(me, w, 204, 'crossed the ' || relit_n || '-relit threshold');
  end if;
  if relit_n >= 100 and random() < 0.15 then
    inv := _give(me, w, 110, 1, inv);
    shard := true;
  end if;
  return jsonb_build_object('ok', true, 'changes', ch, 'inv', inv, 'unique', u, 'star', star, 'shard', shard, 'serial', s, 'validator', vid);
end $$;

-- ════════════════ 055_release_validator.sql ════════════════
-- 055: shut down one of your validators. It goes back to a dark validator (73) in the same place, for anyone
-- to relight (with a heart, for a rarity drawn again): you make room under the three-at-most of 054 to look
-- for a rarer one. What it earned until now is paid first; its seal (item 203) is taken away, whoever holds
-- it; its row is deleted, so it leaves the Validators tab. A crafted validator (block 13) goes the same way.
-- The network's milestones (the Network Star, 204) are minted once per world, so shutting down and relighting
-- doesn't cross them again. Requires 054_three_validators.sql. Replayable without error.

create or replace function public._core_relight(w text, px int, py int, pz int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); pl players; inv jsonb := '{}'; s int; ch jsonb := '[]'; u jsonb; star jsonb; solid boolean;
        relit_n int; shard boolean := false; rarity text; stats jsonb; vid bigint;
begin
  pl := _player(me, w);
  if _cell(w, px, py, pz) <> 73 then return _no('not a dark validator', jsonb_build_object('cell', _cell(w, px, py, pz))); end if;
  for i in 0..2 loop
    solid := coalesce((select rb.solid from rule_blocks rb where rb.id = _cell_soft(w, px + 2, py + i, pz + 2)), false);
    if not solid then return _no('rebuild the fourth column first'); end if;
  end loop;
  -- three at most per player (whatever their state): a fourth ruin stays for someone else
  if (select count(*) from validators v where v.world = w and v.owner = me) >= 3 then
    return _no('three validators at most');
  end if;
  if _count(me, w, 105) < 1 then return _no('needs a validator heart'); end if;
  inv := _give(me, w, 105, -1, inv);
  update players set serial = serial + 1 where user_id = me and world = w returning serial into s;
  ch := ch || _set(w, px, py, pz, 74, me, pl.name, s);
  rarity := _pick_rarity();
  stats := _validator_stats(rarity, 1);
  insert into validators (world, x, y, z, owner, owner_name, state, rarity, level, gwei_per_cycle, maintenance_cost, reanimated_at, last_cycle_at)
    values (w, px, py, pz, me, pl.name, 'active', rarity, 1, (stats ->> 'gwei_per_cycle')::int, (stats ->> 'maintenance_cost')::int, now(), now())
    on conflict (world, x, y, z) do update set owner = excluded.owner, owner_name = excluded.owner_name, state = 'active',
      rarity = excluded.rarity, level = 1, gwei_per_cycle = excluded.gwei_per_cycle, maintenance_cost = excluded.maintenance_cost,
      missed_cycles = 0, reanimated_at = now(), last_cycle_at = now()
    returning id into vid;
  u := _mint(me, w, 203, px || ', ' || py || ', ' || pz);
  update uniques set validator_id = vid where user_id = me and world = w and serial = (u ->> 'serial')::int;
  select count(*) into relit_n from blocks where world = w and id = 74;
  -- each milestone once in a world: a validator shut down and relit doesn't cross it a second time
  if relit_n = any (array[3, 10, 25, 50, 100])
     and not exists (select 1 from uniques where world = w and item = 204 and place = 'crossed the ' || relit_n || '-relit threshold') then
    star := _mint(me, w, 204, 'crossed the ' || relit_n || '-relit threshold');
  end if;
  if relit_n >= 100 and random() < 0.15 then
    inv := _give(me, w, 110, 1, inv);
    shard := true;
  end if;
  return jsonb_build_object('ok', true, 'changes', ch, 'inv', inv, 'unique', u, 'star', star, 'shard', shard, 'serial', s, 'validator', vid);
end $$;

create or replace function public._core_release_validator(w text, validator_id bigint) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); v validators; ch jsonb := '[]'; cur int; seals int[];
begin
  perform _player(me, w);
  select * into v from validators vv where vv.id = _core_release_validator.validator_id and vv.world = w for update;
  if not found then return _no('unknown validator'); end if;
  if v.owner is distinct from me then return _no('not your validator'); end if;
  -- what it earned so far is yours
  perform _tick_validator(w, v.id);
  select coalesce(array_agg(u.serial), '{}') into seals from uniques u where u.world = w and u.item = 203 and u.validator_id = v.id and u.user_id = me;
  delete from uniques u where u.world = w and u.item = 203 and u.validator_id = v.id;
  cur := _cell(w, v.x, v.y, v.z);
  if cur in (13, 74) then ch := ch || _set(w, v.x, v.y, v.z, 73, null, null, null); end if;
  delete from validators where id = v.id;
  return jsonb_build_object('ok', true, 'changes', ch, 'seals', to_jsonb(seals), 'gwei', _gwei_balance(me, w),
    'released', jsonb_build_object('x', v.x, 'y', v.y, 'z', v.z, 'rarity', v.rarity, 'level', v.level));
end $$;

create or replace function public.act_release_validator(w text, validator_id bigint) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w);
begin
  if not _rate(me, 'release_validator', 0.2, 2) then return _no('too many actions'); end if;
  return _core_release_validator(w, validator_id);
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 056_delete_account.sql ════════════════
-- 056: delete your account, from the game itself (the App Store and Google Play ask for it). Typing your
-- nickname confirms it. Your validators go back to dark ruins for anyone (their seals with them, whoever holds
-- them); the blocks you placed stay in the world but no longer carry your name, nor does the block history;
-- your days played and your error reports lose you; then the account itself goes, and with it, by cascade,
-- everything else that is yours in every world: your saves, bag, uniques, Gwei cosmetics, plots, chests'
-- ownership, chat lines, signs, trades, reports, nickname and password, recovery code. What the law keeps:
-- the purchases paid in euros (billing.purchases, 10 years, accounting), with the nickname and the old account
-- id they were bought with; that id is never given again, so no one else gets the pieces back.
-- Requires 046_logins.sql, 053_play_days.sql. Replayable without error.

create or replace function public.act_delete_account(confirm text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); lk text; v record; nv int := 0;
begin
  if me is null then raise exception 'not signed in'; end if;
  if not _rate(me, 'delete_account', 0.1, 2) then return _no('too many actions'); end if;
  select login_key into lk from logins where user_id = me;
  -- your nickname (any case), or "delete" for a guest game that never had one
  if lower(trim(coalesce(confirm, ''))) <> coalesce(lk, 'delete') then
    return _no('type your nickname to confirm');
  end if;
  for v in select id, world, x, y, z from validators where owner = me loop
    delete from uniques u where u.item = 203 and u.validator_id = v.id;
    update blocks b set id = 73, placed_by = null, placed_name = null
      where b.world = v.world and b.x = v.x and b.y = v.y and b.z = v.z and b.id in (13, 74);
    delete from validators where id = v.id;
    nv := nv + 1;
  end loop;
  update blocks set placed_by = null, placed_name = null where placed_by = me::text;
  update block_history set actor = null, actor_name = null where actor = me;
  update client_errors set user_id = null where user_id = me;
  delete from play_days where who = coalesce(lk, me::text) or who = me::text;
  delete from moved_accounts where old_id = me or lower(login) = lk;
  delete from auth.users where id = me;
  return jsonb_build_object('ok', true, 'validators', nv);
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ rules.sql ════════════════
-- Game rules for server-side arbitration. FILE GENERATED by tools/rules.mjs: do not edit by hand.
